/* ════════════════════════════════════════════════════════════════
   EVOLUTION
   ════════════════════════════════════════════════════════════════ */

.evolution-screen {
  background: radial-gradient(circle at 50% 52%, #2d6b4b, #0e2a1e 62%, #071a12);
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  z-index: 60;
}
.evo-bg {
  position: absolute; inset: 0;
  background:
    radial-gradient(circle at 50% 52%, rgba(255, 238, 160, .2), transparent 30%),
    radial-gradient(circle at 20% 20%, rgba(115, 220, 150, .14), transparent 34%),
    radial-gradient(circle at 80% 82%, rgba(255, 143, 171, .13), transparent 36%);
}
.evo-rays {
  position: absolute; left: 50%; top: 48%;
  width: 140vmax; height: 140vmax;
  transform: translate(-50%, -50%);
  background: repeating-conic-gradient(from 0deg, rgba(255, 240, 170, .09) 0deg 4deg, transparent 4deg 12deg);
  animation: evoSpin 40s linear infinite;
  mask-image: radial-gradient(circle, #000 0 18%, transparent 62%);
  -webkit-mask-image: radial-gradient(circle, #000 0 18%, transparent 62%);
}
@keyframes evoSpin { to { transform: translate(-50%,-50%) rotate(360deg); } }
.evo-sparkles { position: absolute; inset: 0; pointer-events: none; overflow: hidden; }
.evo-star {
  position: absolute;
  width: 10px; height: 10px;
  background: #fff6bd;
  clip-path: polygon(50% 0, 61% 35%, 98% 35%, 68% 57%, 79% 91%, 50% 70%, 21% 91%, 32% 57%, 2% 35%, 39% 35%);
  animation: evoStar 3s linear infinite;
}
@keyframes evoStar {
  0% { opacity: 0; transform: translateY(20vh) scale(.3) rotate(0); }
  20% { opacity: 1; }
  100% { opacity: 0; transform: translateY(-50vh) scale(1.1) rotate(240deg); }
}
.evo-stage {
  position: relative;
  width: min(88vw, 720px);
  height: min(48vh, 440px);
  display: flex;
  align-items: flex-end;
  justify-content: center;
  z-index: 2;
}
.evo-figure {
  position: absolute;
  bottom: 0;
  width: min(56vw, 330px);
  height: 100%;
  display: grid; place-items: center;
  transition: opacity .6s, transform .8s var(--ease), filter .6s;
}
.evo-figure svg { width: 100%; height: 100%; overflow: visible; }
.evo-figure.old { opacity: 1; animation: evoShake .5s ease-in-out infinite; filter: brightness(1.25) drop-shadow(0 0 30px rgba(255,240,170,.7)); }
.evo-figure.old.gone { opacity: 0; transform: scale(.3) translateY(50px); filter: brightness(4) blur(12px); animation: none; }
.evo-figure.new { opacity: 0; transform: scale(.55) translateY(40px); filter: brightness(3) blur(10px); }
.evo-figure.new.reveal { opacity: 1; transform: none; filter: drop-shadow(0 24px 22px rgba(3, 18, 11, .4)); transition: opacity .8s, transform 1.1s var(--ease), filter 1s; }
@keyframes evoShake { 0%,100% { transform: translateX(0);} 25% { transform: translateX(-4px);} 75% { transform: translateX(4px);} }
.evo-silhouette {
  position: absolute; bottom: 0;
  width: min(56vw, 330px); height: 100%;
  background: radial-gradient(ellipse at 50% 58%, rgba(255,255,255,.85), rgba(255,244,190,.2) 55%, transparent 68%);
  opacity: 0;
  filter: blur(14px);
  transition: opacity .5s;
  pointer-events: none;
}
.evo-silhouette.flash { opacity: 1; animation: evoFlash .9s ease-out; }
@keyframes evoFlash { 0% { opacity: 0; transform: scale(.5);} 35% { opacity: 1; transform: scale(1.4);} 100% { opacity: 0; transform: scale(1.9);} }
.evo-copy { position: relative; z-index: 3; text-align: center; color: var(--cream); margin-top: 8px; padding: 0 16px; }
.evo-copy .eyebrow { color: var(--gold); opacity: 1; }
.evo-copy h2 { margin: 0; font-family: var(--display); font-size: clamp(1.6rem, 5vw, 3rem); text-shadow: 0 4px 20px rgba(0,0,0,.4); }
.evo-copy p { margin: 8px auto 0; max-width: 540px; color: rgba(255,249,234,.72); font-size: clamp(.82rem, 2.3vw, .98rem); }
.evo-skip { position: absolute; right: 16px; bottom: calc(14px + var(--safe-b)); z-index: 4; color: var(--cream); background: rgba(255,255,255,.1); border-color: rgba(255,255,255,.2); }

/* ════════════════════════════════════════════════════════════════
   ENDING
   ════════════════════════════════════════════════════════════════ */

.ending-screen {
