/* ════════════════════════════════════════════════════════════════
   MODALS
   ════════════════════════════════════════════════════════════════ */

.modal-layer {
  position: absolute; inset: 0;
  z-index: 50;
  display: grid; place-items: center;
  padding: calc(12px + var(--safe-t)) 12px calc(12px + var(--safe-b));
  background: rgba(7, 25, 17, .6);
  backdrop-filter: blur(5px);
  animation: fadeIn .2s;
}
@keyframes fadeIn { from { opacity: 0; } }
.modal {
  width: min(720px, 100%);
  max-height: 100%;
  display: flex; flex-direction: column;
  border-radius: 26px;
  background: linear-gradient(180deg, #fffdf4, #f3e8cc);
  box-shadow: 0 30px 80px rgba(3, 18, 11, .5), inset 0 2px 0 #fff;
  border: 3px solid #e2d1a9;
  animation: modalIn .28s var(--ease);
  overflow: hidden;
}
@keyframes modalIn { from { opacity: 0; transform: translateY(18px) scale(.97);} }
.modal-head {
  display: flex; align-items: center; justify-content: space-between;
  padding: 14px 18px 10px;
  border-bottom: 2px dashed rgba(22,51,42,.14);
}
.modal-head h3 { margin: 0; font-family: var(--display); font-size: 1.35rem; letter-spacing: -.01em; }
.modal-close {
  width: 36px; height: 36px; border-radius: 50%;
  background: rgba(22,51,42,.08);
  font-size: .85rem; font-weight: 900;
}
.modal-body { padding: 12px 16px; overflow-y: auto; -webkit-overflow-scrolling: touch; }
.modal-foot { padding: 10px 16px calc(14px + var(--safe-b)); display: flex; gap: 8px; justify-content: flex-end; flex-wrap: wrap; }
.modal-foot:empty { display: none; }

.party-list { display: grid; gap: 8px; }
.party-row {
  display: flex; align-items: center; gap: 10px;
  padding: 8px; border-radius: 16px;
  background: #fffdf5;
  border: 2px solid rgba(22,51,42,.1);
  box-shadow: 0 3px 0 rgba(22,51,42,.08);
}
.party-row.active { border-color: var(--gold-deep); background: #fff8de; }
.party-art { width: 56px; height: 68px; flex: none; }
.party-art svg { width: 100%; height: 100%; }
.party-main { flex: 1; min-width: 0; }
.party-name { font-size: .9rem; font-weight: 900; }
.party-name small { font-size: .64rem; font-weight: 800; color: var(--ink-soft); margin-left: 4px; }
.party-sub { display: flex; gap: 5px; align-items: center; margin: 2px 0 4px; flex-wrap: wrap; }
.party-bar { height: 7px; border-radius: 7px; background: #dbe2d5; overflow: hidden; }
.party-bar i { display: block; height: 100%; background: linear-gradient(90deg, #7cdd96, #3db765); border-radius: 7px; }
.party-bar i.mid { background: linear-gradient(90deg, #ffe08a, #e6a92e); }
.party-bar i.low { background: linear-gradient(90deg, #ff9b9b, #d94747); }
.party-hp { font-size: .62rem; font-weight: 800; color: var(--ink-soft); margin-top: 2px; }
.party-actions { display: flex; flex-direction: column; gap: 4px; }
.party-actions .btn { padding: 6px 10px; font-size: .62rem; }
.party-note { margin: 6px 0 0; font-size: .68rem; color: var(--ink-soft); line-height: 1.4; }

.bag-list { display: grid; gap: 8px; }
.bag-row {
  display: flex; align-items: center; gap: 11px;
  padding: 9px 11px; border-radius: 16px;
  background: #fffdf5; border: 2px solid rgba(22,51,42,.1);
}
.bag-row .bag-ic {
  width: 42px; height: 42px; flex: none; border-radius: 13px;
  display: grid; place-items: center; font-size: 1.3rem;
  background: linear-gradient(160deg, #e8f7df, #c8e8c9);
  box-shadow: inset 0 1px 0 #fff;
}
.bag-row .bag-main { flex: 1; }
.bag-row .bag-name { font-size: .82rem; font-weight: 900; }
.bag-row .bag-desc { font-size: .64rem; color: var(--ink-soft); line-height: 1.35; }
.bag-row .bag-count { font-size: .8rem; font-weight: 900; color: var(--leaf-deep); background: rgba(79,174,114,.14); padding: 3px 9px; border-radius: 99px; }

.quest-list { display: grid; gap: 9px; }
.quest-row {
  display: flex; gap: 10px; align-items: flex-start;
  padding: 10px 12px; border-radius: 15px;
  background: #fffdf5; border: 2px solid rgba(22,51,42,.1);
}
.quest-row .q-badge {
  width: 34px; height: 34px; flex: none; border-radius: 10px;
  display: grid; place-items: center;
  background: linear-gradient(145deg, #ffe49b, #e3ac42);
  color: #6b4511; font-weight: 900;
}
.quest-row.done { opacity: .65; }
.quest-row.done .q-badge { background: linear-gradient(145deg, #9be8ad, #47a86b); color: #fff; }
.quest-row h4 { margin: 1px 0 2px; font-size: .82rem; }
.quest-row p { margin: 0; font-size: .68rem; color: var(--ink-soft); line-height: 1.4; }

.map-wrap { display: grid; grid-template-columns: 1fr auto; gap: 12px; align-items: start; }
.map-canvas { width: 100%; border-radius: 14px; border: 2px solid rgba(22,51,42,.16); display: block; background: #2f6d4a; image-rendering: pixelated; }
.map-legend { display: grid; gap: 5px; font-size: .62rem; font-weight: 700; color: var(--ink-soft); }
.map-legend span { display: flex; align-items: center; gap: 5px; }
.map-legend i { width: 10px; height: 10px; border-radius: 3px; display: inline-block; }
.map-legend .you { background: #fff5be; }
.map-legend .npc { background: #ff8fab; }
.map-legend .seal { background: #ffd166; }
.map-legend .shrine { background: #c7a4ff; }

.shop-grid { display: grid; gap: 8px; }
.shop-row {
  display: flex; align-items: center; gap: 10px;
  padding: 9px 11px; border-radius: 14px;
  background: #fffdf5; border: 2px solid rgba(22,51,42,.1);
}
.shop-row .bag-ic { width: 40px; height: 40px; flex: none; border-radius: 12px; display: grid; place-items: center; font-size: 1.25rem; background: linear-gradient(160deg, #fff1c9, #f3d894); }
.shop-row .bag-main { flex: 1; }
.shop-row .bag-name { font-size: .82rem; font-weight: 900; }
.shop-row .bag-desc { font-size: .62rem; color: var(--ink-soft); }
.shop-row .buy { padding: 7px 12px; border-radius: 99px; background: var(--ink); color: var(--cream); font-size: .68rem; font-weight: 900; }
.shop-row .buy:disabled { opacity: .35; }
.coin-pill { display: inline-flex; align-items: center; gap: 5px; padding: 4px 10px; border-radius: 99px; background: rgba(255,209,102,.25); color: #6b4511; font-size: .72rem; font-weight: 900; }

.dex-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(112px, 1fr)); gap: 7px; }
.dex-card { padding: 8px; border-radius: 13px; background: #fffdf5; border: 2px solid rgba(22,51,42,.1); text-align: center; }
.dex-card .dex-art { width: 100%; aspect-ratio: 4/5; }
.dex-card .dex-art svg { width: 100%; height: 100%; }
.dex-card.locked { opacity: .38; filter: grayscale(1); }
.dex-card .dex-name { font-size: .68rem; font-weight: 900; }

.big-toast {
  position: absolute;
  left: 50%; top: 38%;
  transform: translate(-50%, -50%);
  z-index: 55;
  padding: 12px 28px;
  border-radius: 99px;
  background: rgba(17, 49, 37, .92);
  color: #ffe9a8;
  font-size: clamp(.9rem, 2.5vw, 1.15rem);
  font-weight: 900;
  letter-spacing: .03em;
  box-shadow: 0 16px 40px rgba(5,25,16,.4);
  border: 1px solid rgba(255,255,255,.16);
  animation: bigToast .35s var(--ease);
  pointer-events: none;
}
@keyframes bigToast { from { opacity: 0; transform: translate(-50%,-50%) scale(.75);} }

.transition {
  position: absolute; inset: 0; z-index: 70;
  display: grid; place-items: center;
  background: #102f23;
  animation: transitionIn .35s ease-in forwards;
}
.transition.out { animation: transitionOut .45s ease-out forwards; }
.transition-flower { font-size: 4rem; color: #ffe9a8; animation: spinFlower .8s ease-in-out infinite; }
@keyframes transitionIn { from { clip-path: circle(0% at 50% 50%);} to { clip-path: circle(150% at 50% 50%);} }
@keyframes transitionOut { from { clip-path: circle(150% at 50% 50%);} to { clip-path: circle(0% at 50% 50%);} }
@keyframes spinFlower { 50% { transform: rotate(180deg) scale(1.15);} 100% { transform: rotate(360deg);} }

/* ════════════════════════════════════════════════════════════════
   RESPONSIVE
   ════════════════════════════════════════════════════════════════ */

@media (pointer: coarse), (max-width: 900px) {
