  .title-blurb { display: none; }
  .title-actions { margin-top: 20px; }
  .btn.big { padding: 14px 28px; font-size: 1rem; }
  .title-foot { font-size: .62rem; bottom: calc(8px + var(--safe-b)); }
  .title-starters { margin-top: 10px; min-height: 80px; }
  .hud-player { padding: 5px 10px 5px 5px; }
  .hud-avatar { width: 32px; height: 32px; font-size: 1rem; }
  .hud-name { font-size: .72rem; }
  .hud-seals { margin-top: 0; }
  .hud-buttons .sound-hud { display: none; }
  .quest-chip { padding: 8px 10px; }
  .q-text { font-size: .64rem; }
  .touch-controls { padding-bottom: 2px; }
  .dpad { width: 132px; height: 132px; }
  .dp { width: 44px; height: 44px; }
  .dp.up, .dp.down { left: 44px; }
  .dp.left, .dp.right { top: 44px; }
  .dp-center { inset: 44px; }
  .action-btn { width: 68px; height: 68px; font-size: 1.4rem; }
