  .dialogue { padding: 10px; gap: 9px; }
  .dialogue-portrait { width: 48px; height: 48px; border-radius: 14px; }
  .dialogue-text { font-size: .78rem; }
  .party-art { width: 46px; height: 58px; }
  .map-wrap { grid-template-columns: 1fr; }
  .modal-head h3 { font-size: 1.15rem; }
  .evo-stage { height: 40vh; }
  .evo-copy h2 { font-size: 1.5rem; }
}
@media (max-height: 560px) and (orientation: landscape) {
  .battle-ui { grid-template-columns: minmax(0,1fr) 48%; grid-template-rows: auto auto; padding: 7px 12px calc(7px + var(--safe-b)); }
  .battle-msg { grid-row: 1/3; min-height: 0; font-size: .78rem; }
  .battle-actions { grid-column: 2; grid-row: 1; }
  .battle-tabs { grid-column: 2; grid-row: 2; }
  .battle-info.enemy { top: 3%; left: 3%; width: 190px; }
  .battle-info.player { bottom: 10%; right: 3%; width: 190px; }
  .battle-mon { width: clamp(130px, 26vh, 220px); }
  .battle-mon.enemy { top: 4%; }
  .battle-mon.player { bottom: 5%; }
  .battle-platform.enemy { bottom: 30%; }
  .battle-platform.player { bottom: 3%; }
  .quest-chip { bottom: calc(10px + var(--safe-b)); width: 210px; }
  .interact-prompt { bottom: calc(12px + var(--safe-b)); }
  .dpad { width: 118px; height: 118px; }
  .dp { width: 40px; height: 40px; }
  .dp.up, .dp.down { left: 39px; }
  .dp.left, .dp.right { top: 39px; }
  .dp-center { inset: 39px; }
  .action-btn { width: 60px; height: 60px; }
  .title-starters { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }
}

