import { portraitSVG, typeColors, monsterSVG } from './art.js';
import { TYPE_META, SPECIES } from './data.js';

export const $ = (sel, root = document) => root.querySelector(sel);
export const $$ = (sel, root = document) => [...root.querySelectorAll(sel)];

export function typeChip(type) {
  const m = TYPE_META[type] || TYPE_META.Leaf;
  return `<span class="tchip" style="background:${m.color}">${m.icon} ${m.label}</span>`;
}

export function typeChipSmall(type) {
  const m = TYPE_META[type] || TYPE_META.Leaf;
  return `<span class="tchip" style="background:${m.color};font-size:.46rem">${m.label}</span>`;
}

export function hpClass(ratio) { return ratio <= .22 ? 'low' : ratio <= .5 ? 'mid' : ''; }

/* ─────────────── dialogue ─────────────── */

const dialogue = {
  open: false, lines: [], index: 0, name: '', portrait: 'professor',
  typing: false, timer: null, onDone: null, text: '',
};

export function isDialogueOpen() { return dialogue.open; }

export function showDialogue({ name, portrait = 'professor', lines, onDone = null }) {
  const box = $('#dialogue');
  dialogue.open = true;
  dialogue.lines = Array.isArray(lines) ? lines.slice() : [lines];
  dialogue.index = 0;
  dialogue.name = name;
  dialogue.portrait = portrait;
  dialogue.onDone = onDone;
  $('#dialogue-name').textContent = name;
  $('#dialogue-portrait').innerHTML = portraitSVG(portrait);
  box.classList.remove('hidden');
  typeLine();
}

function typeLine() {
  clearInterval(dialogue.timer);
  const el = $('#dialogue-text');
  const full = dialogue.lines[dialogue.index] || '';
  dialogue.text = full;
  dialogue.full = full;
  dialogue.typing = true;
  el.textContent = '';
  let i = 0;
  dialogue.timer = setInterval(() => {
    i += 1;
    el.textContent = full.slice(0, i);
    if (i >= full.length) {
      clearInterval(dialogue.timer);
      dialogue.typing = false;
    }
  }, 14);
}

export function advanceDialogue() {
  if (!dialogue.open) return false;
  if (dialogue.typing) {
    clearInterval(dialogue.timer);
    $('#dialogue-text').textContent = dialogue.full || dialogue.text;
    dialogue.typing = false;
    return true;
  }
  if (dialogue.index < dialogue.lines.length - 1) {
    dialogue.index++;
    typeLine();
    return true;
  }
  closeDialogue();
  return true;
}

export function closeDialogue() {
  clearInterval(dialogue.timer);
  dialogue.open = false;
  $('#dialogue').classList.add('hidden');
  const cb = dialogue.onDone;
  dialogue.onDone = null;
  if (cb) setTimeout(cb, 60);
}

/* ─────────────── modal ─────────────── */

const modal = { open: false, onClose: null };

export function openModal({ title, body, foot = '', onClose = null, wide = false }) {
  modal.open = true;
  modal.onClose = onClose;
  $('#modal-title').textContent = title;
  $('#modal-body').innerHTML = body;
  $('#modal-foot').innerHTML = foot;
  $('#modal').style.width = wide ? 'min(880px, 100%)' : '';
  $('#modal-layer').classList.remove('hidden');
  dialogStackAdd();
}
export function isModalOpen() { return modal.open; }
export function closeModal() {
  if (!modal.open) return;
  modal.open = false;
  $('#modal-layer').classList.add('hidden');
  $('#modal-body').innerHTML = '';
  $('#modal-foot').innerHTML = '';
  const cb = modal.onClose;
  modal.onClose = null;
  dialogStackRemove();
  if (cb) cb();
}

/* simple stack so Escape/A knows an overlay is active */
let overlayDepth = 0;
function dialogStackAdd() { overlayDepth++; }
function dialogStackRemove() { overlayDepth = Math.max(0, overlayDepth - 1); }
export function overlayActive() { return modal.open || dialogue.open; }

/* ─────────────── toasts / big toast ─────────────── */

export function toast(text, kind = '') {
  const wrap = $('#toasts');
  const el = document.createElement('div');
  el.className = `toast ${kind}`;
  el.textContent = text;
  wrap.appendChild(el);
  setTimeout(() => el.remove(), 3200);
}

let bigTimer = null;
export function bigToast(text, ms = 1600) {
  const el = $('#big-toast');
  el.textContent = text;
  el.classList.remove('hidden');
  clearTimeout(bigTimer);
  bigTimer = setTimeout(() => el.classList.add('hidden'), ms);
}

/* ─────────────── transition ─────────────── */

export function transition(duration = 350) {
  return new Promise(resolve => {
    const el = $('#transition');
    el.classList.remove('hidden', 'out');
    void el.offsetWidth;
    setTimeout(() => {
      el.classList.add('out');
      setTimeout(() => {
        el.classList.add('hidden');
        el.classList.remove('out');
        resolve();
      }, 420);
    }, duration);
  });
}

/* ─────────────── small creature renderers ─────────────── */

export function creatureMini(sp, size = null) {
  const style = size ? ` style="width:${size}px;height:${Math.round(size * 1.25)}px"` : '';
  return `<div class="tc-art"${style}>${monsterSVG(sp)}</div>`;
}

export function partyRowHTML(c, index, active = false) {
  const sp = SPECIES[c.species];
  const max = Math.max(1, Math.round(c.hp));
  const ratio = c.hp / max;
  const pct = Math.max(0, Math.min(100, ratio * 100));
  return `<div class="party-row ${active ? 'active' : ''}" data-index="${index}">
    <div class="party-art">${monsterSVG(sp)}</div>
    <div class="party-main">
      <div class="party-name">${sp.name} <small>Lv. ${c.level}</small></div>
      <div class="party-sub">${typeChipSmall(sp.type)}<span class="hint">${sp.title}</span></div>
      <div class="party-bar"><i class="${hpClass(ratio)}" style="width:${pct}%"></i></div>
      <div class="party-hp">${Math.max(0, Math.round(c.hp))} / ${max} HP · ${c.xp}/${xpNeeded(c)} XP</div>
    </div>
    <div class="party-actions">
      ${active ? '<span class="hint" style="font-size:.58rem;font-weight:900">LEAD</span>' : `<button class="btn ghost" data-lead="${index}">Lead</button>`}
    </div>
  </div>`;
}

function xpNeeded(c) {
  return 12 + c.level * 9;
}

export function teamGridHTML(state, mode = 'overworld') {
  return state.party.map((c, i) => {
    const sp = SPECIES[c.species];
    const max = Math.max(1, Math.round(c.hp));
    const ratio = c.hp / max;
    const pct = Math.max(0, Math.min(100, ratio * 100));
    return `<button class="team-card ${i === 0 ? 'active' : ''} ${c.hp <= 0 ? 'fainted' : ''}" data-team="${i}" ${c.hp <= 0 ? 'disabled' : ''}>
      <div class="tc-art">${monsterSVG(sp)}</div>
      <div>
        <div class="tc-name">${sp.name} <span class="hint">Lv.${c.level}</span></div>
        <div class="tc-sub">${sp.type}${c.hp <= 0 ? ' · fainted' : ''}</div>
        <div class="hp-mini"><i style="width:${pct}%"></i></div>
      </div>
    </button>`;
  }).join('');
}

/* ════════════════════════════════════════════════════════════════
   overworld.js — canvas world, movement, people & little wonders
   ════════════════════════════════════════════════════════════════ */

import { MAP, MAP_W, MAP_H, TILE, WORLD_OBJECTS, BUILDINGS, PROPS, NPCS, SIGNS, SPECIES, regionName, encounterZone } from './data.js';

const DIRS = {
  up: { x: 0, y: -1 },
  down: { x: 0, y: 1 },
  left: { x: -1, y: 0 },
  right: { x: 1, y: 0 },
};

const hash = (x, y, s = 1) => {
  const n = Math.sin(x * 127.1 + y * 311.7 + s * 74.7) * 43758.5453;
  return n - Math.floor(n);
};

function roundRect(ctx, x, y, w, h, r) {
  const rr = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + rr, y);
  ctx.arcTo(x + w, y, x + w, y + h, rr);
  ctx.arcTo(x + w, y + h, x, y + h, rr);
  ctx.arcTo(x, y + h, x, y, rr);
  ctx.arcTo(x, y, x + w, y, rr);
  ctx.closePath();
}

export class Overworld {
  constructor(canvas, game) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d', { alpha: false });
    this.game = game;
    this.state = null;
    this.running = false;
    this.paused = true;
    this.time = 0;
    this.last = 0;
    this.dpr = 1;
    this.w = 1; this.h = 1;
    this.ts = 48;
    this.camX = 0; this.camY = 0;
    this.px = 10; this.py = 29;
    this.vx = 10; this.vy = 29;
    this.dir = 'up';
    this.moving = false;
    this.moveT = 0;
    this.moveDur = 0.15;
    this.fromX = 10; this.fromY = 29;
    this.held = [];
    this.walkPhase = 0;
    this.bump = 0;
    this.trail = [];
    this.compX = 10; this.compY = 29;
    this.ambient = [];
    this.stepCooldown = 0;
    this.grassSteps = 0;
    this.nearest = null;
    this.frame = 0;
    this.resize();
    this._onResize = () => this.resize();
    window.addEventListener('resize', this._onResize);
    window.addEventListener('orientationchange', () => setTimeout(() => this.resize(), 120));
    this._loop = this._loop.bind(this);
  }

  setState(state) {
    this.state = state;
    this.px = state.player.x;
    this.py = state.player.y;
    this.vx = this.px; this.vy = this.py;
    this.dir = state.player.dir || 'up';
    this.compX = this.px; this.compY = this.py;
    this.trail = [];
    this.nearest = null;
    this.updateCamera(true);
  }

  resize() {
    const rect = this.canvas.getBoundingClientRect();
    this.w = Math.max(1, rect.width);
    this.h = Math.max(1, rect.height);
    this.dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.canvas.width = Math.round(this.w * this.dpr);
    this.canvas.height = Math.round(this.h * this.dpr);
    // camera zoom: keep the phone view intimate but not claustrophobic
    const fit = Math.min(this.w / 11, this.h / 8.4);
    this.ts = Math.max(34, Math.min(68, fit));
    this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    this.ctx.imageSmoothingEnabled = true;
    this.updateCamera(true);
    this.makeAmbient();
  }

  makeAmbient() {
    this.ambient = [];
    const count = Math.round(Math.min(26, (this.w * this.h) / 52000));
    for (let i = 0; i < count; i++) {
      this.ambient.push({
        x: Math.random() * this.w,
        y: Math.random() * this.h,
        s: 2 + Math.random() * 4,
        vy: 4 + Math.random() * 12,
        vx: -6 + Math.random() * 18,
        rot: Math.random() * 6.28,
        vr: (Math.random() - .5) * 2,
        a: .22 + Math.random() * .4,
        kind: Math.random() < .55 ? 'petal' : 'mote',
        ph: Math.random() * 6.28,
      });
    }
  }

  start() {
    if (this.running) return;
    this.running = true;
    this.last = performance.now();
    requestAnimationFrame(this._loop);
  }

  stop() {
    this.running = false;
    this.paused = true;
  }

  setPaused(p) {
    this.paused = p;
    if (!p) this.last = performance.now();
    if (p) this.held = [];
  }

  setDirection(dir, down) {
    const i = this.held.indexOf(dir);
    if (down && i < 0) this.held.push(dir);
    if (!down && i >= 0) this.held.splice(i, 1);
    if (down) this.dir = dir;
  }

  clearHeld() { this.held = []; }

  get targetDir() {
    if (!this.held.length) return null;
    return this.held[this.held.length - 1];
  }

  _loop(now) {
    if (!this.running) return;
    const dt = Math.min(.05, (now - this.last) / 1000 || 0);
    this.last = now;
    this.time += dt;
    this.frame++;
    if (!this.paused && this.state) this.update(dt);
    this.render();
    requestAnimationFrame(this._loop);
  }

  update(dt) {
    if (this.stepCooldown > 0) this.stepCooldown -= dt;
    if (this.bump > 0) this.bump = Math.max(0, this.bump - dt * 5);

    if (this.moving) {
      this.moveT += dt / this.moveDur;
      if (this.moveT >= 1) {
        this.moving = false;
        this.moveT = 0;
        this.vx = this.px; this.vy = this.py;
        this.arrive();
      } else {
        const t = this.moveT;
        const e = t * t * (3 - 2 * t);
        this.vx = this.fromX + (this.px - this.fromX) * e;
        this.vy = this.fromY + (this.py - this.fromY) * e;
        this.walkPhase += dt * 12;
      }
    } else {
      const d = this.targetDir;
      if (d && !this.game.overlayBlocking()) this.tryMove(d);
    }

    // companion glide
    const tx = this.trail.length ? this.trail[0].x : this.px;
    const ty = this.trail.length ? this.trail[0].y : this.py;
    const k = 1 - Math.exp(-dt * 8.5);
    this.compX += (tx - this.compX) * k;
    this.compY += (ty - this.compY) * k;

    // ambient
    for (const p of this.ambient) {
      p.x += (p.vx + Math.sin(this.time * .8 + p.ph) * 4) * dt;
      p.y += p.vy * dt;
      p.rot += p.vr * dt;
      if (p.y > this.h + 10) { p.y = -10; p.x = Math.random() * this.w; }
      if (p.x < -12) p.x = this.w + 10;
      if (p.x > this.w + 12) p.x = -10;
    }

    this.updateCamera(false);
    const near = this.getInteractable();
    if ((near && near.key) !== (this.nearest && this.nearest.key)) {
      this.nearest = near;
      this.game.updatePrompt(near);
    }
    // refresh prompt when trainer is defeated etc.
    if (this.frame % 30 === 0 && near) {
      this.nearest = near;
      this.game.updatePrompt(near);
    }
  }

  tryMove(dir) {
    if (this.moving) return;
    const d = DIRS[dir];
    if (!d) return;
    this.dir = dir;
    const nx = this.px + d.x, ny = this.py + d.y;
    if (!this.canWalk(nx, ny)) {
      this.bump = 1;
      // face even when blocked
      this.state.player.dir = dir;
      return;
    }
    this.fromX = this.px; this.fromY = this.py;
    this.trail.unshift({ x: this.px, y: this.py });
    if (this.trail.length > 5) this.trail.pop();
    this.px = nx; this.py = ny;
    this.moving = true;
    this.moveT = 0;
    this.moveDur = 0.145;
    this.state.player.x = nx;
    this.state.player.y = ny;
    this.state.player.dir = dir;
    this.state.player.steps++;
    this.state.stats.steps++;
    const region = regionName(nx, ny);
    if (this.state.location !== region) {
      this.state.location = region;
      this.game.onRegionChange(region);
    }
    this.game.onStep();
  }

  arrive() {
    const c = MAP[this.py] && MAP[this.py][this.px];
    if (c === 'H') {
      this.grassSteps++;
      if (this.stepCooldown <= 0 && this.grassSteps > 1 && Math.random() < .145) {
        this.grassSteps = 0;
        this.stepCooldown = 8;
        this.game.startWildEncounter(encounterZone(this.px, this.py));
      }
    } else {
      this.grassSteps = 0;
    }
    if (this.state.flags.ending) return;
    if (this.px === 35 && this.py === 10 && this.game.sealCount() >= 3 && !this.state.flags.gateOpened) {
      this.state.flags.gateOpened = true;
      this.game.openGate();
    }
  }

  canWalk(x, y) {
    if (x < 0 || y < 0 || x >= MAP_W || y >= MAP_H) return false;
    const c = MAP[y][x];
    if (c === 'T' || c === 'W' || c === 'R') return false;
    for (const b of BUILDINGS) {
      if (x >= b.x && x < b.x + b.w && y >= b.y && y < b.y + b.h) return false;
    }
    for (const p of PROPS) {
      if (p.gate && this.state.flags.gateOpened) continue;
      if (p.x === x && p.y === y) return false;
    }
    for (const n of NPCS) if (n.x === x && n.y === y) return false;
    for (const s of SIGNS) if (s.x === x && s.y === y) return false;
    return true;
  }

  getInteractable() {
    const front = { x: this.px + DIRS[this.dir].x, y: this.py + DIRS[this.dir].y };
    // NPC first (front, then adjacent for friendliness)
    for (const n of NPCS) {
      if (n.x === front.x && n.y === front.y) return this.npcTarget(n, 'npc');
    }
    for (const n of NPCS) {
      const dist = Math.abs(n.x - this.px) + Math.abs(n.y - this.py);
      if (dist === 1) return this.npcTarget(n, 'npc');
    }
    for (const s of SIGNS) if (s.x === front.x && s.y === front.y) return { kind: 'sign', key: 'sign-' + s.id, label: 'Read sign', sign: s };
    for (const p of PROPS) {
      if (p.x === front.x && p.y === front.y) {
        if (p.gate && this.state.flags.gateOpened) return { kind: 'gate', key: 'gate-open', label: 'Shrine Gate', prop: p };
        if (p.gate) return { kind: 'gate', key: 'gate', label: this.game.sealCount() >= 3 ? 'Open the gate' : 'Shrine Gate', prop: p };
        if (p.heal) return { kind: 'heal', key: 'heal-' + p.name, label: p.kind === 'moonwell' ? 'Bathe in the Moonwell' : 'Heal your team', prop: p };
        return { kind: 'prop', key: 'prop-' + p.name, label: p.name, prop: p };
      }
    }
    // doors: show a friendly flavour prompt when facing a building base
    for (const b of BUILDINGS) {
      const doorX = b.x + Math.floor(b.w / 2);
      const doorY = b.y + b.h;
      if (front.x === doorX && (front.y === doorY || (front.x === this.px && this.py === doorY))) {
        return { kind: 'building', key: 'b-0' + b.kind, label: b.name, building: b };
      }
    }
    return null;
  }

  npcTarget(n, kind) {
    if (n.trainer) {
      const done = !!this.state.flags.defeated[n.trainer];
      return { kind: 'npc', key: 'npc-' + n.id + '-' + (done ? 'done' : 'ready'), label: done ? `Talk to ${n.name}` : `Challenge ${n.name}`, npc: n };
    }
    return { kind: 'npc', key: 'npc-' + n.id, label: n.shop ? 'Shop at Pip\'s Petals' : `Talk to ${n.name}`, npc: n };
  }

  updateCamera(instant = false) {
    const targetX = this.vx * this.ts + this.ts / 2 - this.w / 2;
    const targetY = this.vy * this.ts + this.ts * .62 - this.h / 2;
    const maxX = MAP_W * this.ts - this.w;
    const maxY = MAP_H * this.ts - this.h;
    const cx = Math.max(0, Math.min(maxX, targetX));
    const cy = Math.max(0, Math.min(maxY, targetY));
    if (instant) { this.camX = cx; this.camY = cy; }
    else {
      this.camX += (cx - this.camX) * .18;
      this.camY += (cy - this.camY) * .18;
    }
  }

  /* ══════════════════════════════ RENDER ══════════════════════════════ */

  render() {
    if (!this.state) return;
    const ctx = this.ctx;
    const { w, h, ts } = this;
    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    ctx.fillStyle = '#4d9159';
    ctx.fillRect(0, 0, w, h);

    const ox = -this.camX;
    const oy = -this.camY;
    const x0 = Math.max(0, Math.floor(this.camX / ts) - 1);
    const x1 = Math.min(MAP_W - 1, Math.ceil((this.camX + w) / ts) + 1);
    const y0 = Math.max(0, Math.floor(this.camY / ts) - 1);
    const y1 = Math.min(MAP_H - 1, Math.ceil((this.camY + h) / ts) + 2);

    // ground pass
    for (let y = y0; y <= y1; y++) {
      for (let x = x0; x <= x1; x++) {
        this.drawGround(ctx, x, y, ox + x * ts, oy + y * ts, ts);
      }
    }

    // build sorted drawables
    const items = [];
    for (let y = y0; y <= y1; y++) {
      for (let x = x0; x <= x1; x++) {
        const c = MAP[y][x];
        if (c === 'T') items.push({ d: y + .84, f: () => this.drawTree(ctx, ox + x * ts, oy + y * ts, ts, x, y) });
        else if (c === 'R') items.push({ d: y + .5, f: () => this.drawRock(ctx, ox + x * ts, oy + y * ts, ts, x, y) });
      }
    }
    for (const b of BUILDINGS) {
      if (b.x + b.w < x0 || b.x > x1 || b.y + b.h < y0 || b.y > y1) continue;
      items.push({ d: b.y + b.h - .1, f: () => this.drawBuilding(ctx, b, ox, oy, ts) });
    }
    for (const p of PROPS) {
      if (p.x < x0 - 1 || p.x > x1 + 1 || p.y < y0 - 1 || p.y > y1 + 1) continue;
      items.push({ d: p.y + .7, f: () => this.drawProp(ctx, p, ox, oy, ts) });
    }
    for (const s of SIGNS) {
      if (s.x < x0 || s.x > x1 || s.y < y0 || s.y > y1) continue;
      items.push({ d: s.y + .6, f: () => this.drawSign(ctx, s, ox, oy, ts) });
    }
    for (const n of NPCS) {
      if (n.x < x0 - 1 || n.x > x1 + 1 || n.y < y0 - 1 || n.y > y1 + 1) continue;
      items.push({ d: n.y + .82, f: () => this.drawNPC(ctx, n, ox, oy, ts) });
    }
    items.push({ d: this.compY + .8, f: () => this.drawCompanion(ctx, ox, oy, ts) });
    items.push({ d: this.vy + .86, f: () => this.drawPlayer(ctx, ox, oy, ts) });
    items.sort((a, b) => a.d - b.d);
    for (const it of items) it.f();

    // foreground grass when standing inside it
    if (MAP[this.py] && MAP[this.py][this.px] === 'H') {
      const sx = ox + this.vx * ts, sy = oy + this.vy * ts;
      this.drawGrassOverlay(ctx, sx, sy, ts, this.px, this.py, .9);
    }

    // ambient petals / motes (screen space)
    this.drawAmbient(ctx, w, h);

    // soft map-edge fade
    const grad = ctx.createLinearGradient(0, 0, 0, h);
    grad.addColorStop(0, 'rgba(12,40,26,.16)');
    grad.addColorStop(.15, 'rgba(12,40,26,0)');
    ctx.fillStyle = grad; ctx.fillRect(0, 0, w, h);
  }

  drawGround(ctx, x, y, sx, sy, ts) {
    const c = MAP[y][x];
    const n = hash(x, y);
    if (c === 'W') { this.drawWater(ctx, sx, sy, ts, x, y); return; }
    if (c === '#') { this.drawPath(ctx, sx, sy, ts, x, y); return; }
    if (c === '=') { this.drawStone(ctx, sx, sy, ts, x, y); return; }

    // grass base
    const shades = ['#63aa68', '#5fa564', '#68b06d', '#5ba260'];
    ctx.fillStyle = shades[Math.floor(n * shades.length)];
    ctx.fillRect(sx, sy, ts + 1, ts + 1);

    // subtle patch
    if (n > .55) {
      ctx.fillStyle = 'rgba(122, 194, 120, .18)';
      ctx.beginPath();
      ctx.ellipse(sx + ts * (.3 + n * .3), sy + ts * (.4 + n * .2), ts * .38, ts * .22, n * 3, 0, 6.3);
      ctx.fill();
    }

    // grass blades
    ctx.strokeStyle = 'rgba(43, 112, 60, .38)';
    ctx.lineWidth = Math.max(1, ts * .022);
    ctx.lineCap = 'round';
    const blades = 2 + Math.floor(hash(x, y, 3) * 3);
    for (let i = 0; i < blades; i++) {
      const bx = sx + hash(x, y, i + 4) * ts;
      const by = sy + ts * (.45 + hash(x, y, i + 9) * .52);
      const len = ts * (.1 + hash(x, y, i + 14) * .1);
      const lean = (hash(x, y, i + 20) - .5) * ts * .16;
      ctx.beginPath();
      ctx.moveTo(bx, by);
      ctx.quadraticCurveTo(bx + lean * .4, by - len * .6, bx + lean, by - len);
      ctx.stroke();
    }

    if (c === 'H') {
      this.drawTallGrassBase(ctx, sx, sy, ts, x, y);
    } else if (c === ',') {
      this.drawFlowers(ctx, sx, sy, ts, x, y);
    }
  }

  drawFlowers(ctx, sx, sy, ts, x, y) {
    const palette = ['#ffe6f0', '#ffd166', '#ffb3c8', '#e6e0ff', '#fff8d8'];
    const count = 2 + Math.floor(hash(x, y, 2) * 3);
    for (let i = 0; i < count; i++) {
      const fx = sx + ts * (.16 + hash(x, y, i + 31) * .68);
      const fy = sy + ts * (.2 + hash(x, y, i + 41) * .62);
      const col = palette[Math.floor(hash(x, y, i + 51) * palette.length)];
      const r = ts * .045;
      ctx.fillStyle = 'rgba(40, 100, 58, .35)';
      ctx.fillRect(fx - .7, fy, 1.4, ts * .09);
      ctx.fillStyle = col;
      for (let k = 0; k < 5; k++) {
        const a = k / 5 * 6.283 + hash(x, y, i) * 3;
        ctx.beginPath();
        ctx.arc(fx + Math.cos(a) * r * 1.35, fy + Math.sin(a) * r * 1.35, r, 0, 6.3);
        ctx.fill();
      }
      ctx.fillStyle = '#ffd166';
      ctx.beginPath(); ctx.arc(fx, fy, r * .7, 0, 6.3); ctx.fill();
    }
  }

  drawTallGrassBase(ctx, sx, sy, ts, x, y) {
    ctx.fillStyle = 'rgba(30, 94, 50, .34)';
    ctx.beginPath();
    ctx.ellipse(sx + ts * .5, sy + ts * .7, ts * .52, ts * .34, 0, 0, 6.3);
    ctx.fill();
    ctx.strokeStyle = '#2f7d4b';
    ctx.lineWidth = Math.max(1.4, ts * .035);
    ctx.lineCap = 'round';
    for (let i = 0; i < 5; i++) {
      const bx = sx + ts * (.12 + i * .19 + hash(x, y, i) * .05);
      const by = sy + ts * (.94 - hash(x, y, i + 6) * .08);
      const len = ts * (.36 + hash(x, y, i + 11) * .18);
      const sway = Math.sin(this.time * 2.2 + x * .7 + y * .5 + i) * ts * .06;
      ctx.beginPath();
      ctx.moveTo(bx, by);
      ctx.quadraticCurveTo(bx + sway * .5, by - len * .55, bx + sway, by - len);
      ctx.stroke();
      ctx.strokeStyle = i % 2 ? '#3b9157' : '#2f7d4b';
    }
  }

  drawGrassOverlay(ctx, sx, sy, ts, x, y, opacity = 1) {
    ctx.save();
    ctx.globalAlpha = opacity;
    ctx.strokeStyle = '#255f3a';
    ctx.lineWidth = Math.max(1.6, ts * .038);
    ctx.lineCap = 'round';
    for (let i = 0; i < 6; i++) {
      const bx = sx + ts * (.08 + i * .17 + hash(x, y, i + 70) * .06);
      const by = sy + ts * .98;
      const len = ts * (.4 + hash(x, y, i + 80) * .2);
      const sway = Math.sin(this.time * 2.4 + i * 1.3 + x) * ts * .07;
      ctx.beginPath();
      ctx.moveTo(bx, by);
      ctx.quadraticCurveTo(bx + sway * .5, by - len * .6, bx + sway, by - len);
      ctx.stroke();
    }
    ctx.restore();
  }

  drawPath(ctx, sx, sy, ts, x, y) {
    ctx.fillStyle = '#d9c48f';
    ctx.fillRect(sx, sy, ts + 1, ts + 1);
    ctx.fillStyle = 'rgba(255, 248, 214, .18)';
    ctx.fillRect(sx, sy, ts + 1, ts * .5);
    // pebbles
    for (let i = 0; i < 3; i++) {
      const px = sx + ts * (.14 + hash(x, y, i + 4) * .7);
      const py = sy + ts * (.15 + hash(x, y, i + 9) * .7);
      ctx.fillStyle = 'rgba(150, 128, 82, .3)';
      ctx.beginPath(); ctx.ellipse(px, py, ts * .04, ts * .025, hash(x, y, i) * 3, 0, 6.3); ctx.fill();
    }
    // edges against non-path
    ctx.strokeStyle = 'rgba(126, 107, 64, .38)';
    ctx.lineWidth = Math.max(1.5, ts * .03);
    const N = (dx, dy) => {
      const c = (MAP[y + dy] && MAP[y + dy][x + dx]) || 'T';
      return c !== '#' && c !== '=';
    };
    ctx.beginPath();
    if (N(0, -1)) { ctx.moveTo(sx, sy + 1); ctx.lineTo(sx + ts, sy + 1); }
    if (N(0, 1)) { ctx.moveTo(sx, sy + ts - 1); ctx.lineTo(sx + ts, sy + ts - 1); }
    if (N(-1, 0)) { ctx.moveTo(sx + 1, sy); ctx.lineTo(sx + 1, sy + ts); }
    if (N(1, 0)) { ctx.moveTo(sx + ts - 1, sy); ctx.lineTo(sx + ts - 1, sy + ts); }
    ctx.stroke();
    // occasional tuft
    if (hash(x, y, 5) > .8) {
      ctx.strokeStyle = 'rgba(60, 130, 72, .5)';
      ctx.beginPath();
      ctx.moveTo(sx + ts * .8, sy + ts * .88);
      ctx.quadraticCurveTo(sx + ts * .82, sy + ts * .72, sx + ts * .88, sy + ts * .68);
      ctx.stroke();
    }
  }

  drawStone(ctx, sx, sy, ts, x, y) {
    const v = hash(x, y);
    ctx.fillStyle = v > .5 ? '#b9c3ac' : '#b1bca4';
    ctx.fillRect(sx, sy, ts + 1, ts + 1);
    ctx.strokeStyle = 'rgba(90, 105, 82, .32)';
    ctx.lineWidth = Math.max(1, ts * .02);
    ctx.strokeRect(sx + 2, sy + 2, ts - 4, ts - 4);
    if (hash(x, y, 7) > .65) {
      ctx.strokeStyle = 'rgba(90, 105, 82, .2)';
      ctx.beginPath();
      ctx.moveTo(sx + ts * .2, sy + ts * .5);
      ctx.lineTo(sx + ts * .5, sy + ts * .3);
      ctx.lineTo(sx + ts * .8, sy + ts * .55);
      ctx.stroke();
    }
  }

  drawWater(ctx, sx, sy, ts, x, y) {
    const grad = ctx.createLinearGradient(sx, sy, sx, sy + ts);
    grad.addColorStop(0, '#58b6d6');
    grad.addColorStop(1, '#3d8fbe');
    ctx.fillStyle = grad;
    ctx.fillRect(sx, sy, ts + 1, ts + 1);
    // animated waves
    ctx.strokeStyle = 'rgba(220, 252, 255, .4)';
    ctx.lineWidth = Math.max(1, ts * .025);
    const off = Math.sin(this.time * 1.2 + x * .8 + y * .6) * ts * .08;
    ctx.beginPath();
    ctx.moveTo(sx + ts * .1, sy + ts * .3 + off);
    ctx.quadraticCurveTo(sx + ts * .35, sy + ts * .21 + off, sx + ts * .58, sy + ts * .32 + off);
    ctx.quadraticCurveTo(sx + ts * .76, sy + ts * .4 + off, sx + ts * .92, sy + ts * .3 + off);
    ctx.stroke();
    ctx.strokeStyle = 'rgba(220, 252, 255, .22)';
    ctx.beginPath();
    ctx.moveTo(sx + ts * .2, sy + ts * .72 - off);
    ctx.quadraticCurveTo(sx + ts * .45, sy + ts * .64 - off, sx + ts * .7, sy + ts * .74 - off);
    ctx.stroke();
    // shoreline
    ctx.strokeStyle = 'rgba(240, 226, 170, .55)';
    ctx.lineWidth = Math.max(2, ts * .045);
    const isLand = (dx, dy) => {
      const c = (MAP[y + dy] && MAP[y + dy][x + dx]) || 'W';
      return c !== 'W';
    };
    ctx.beginPath();
    if (isLand(0, -1)) { ctx.moveTo(sx, sy + 2); ctx.lineTo(sx + ts, sy + 2); }
    if (isLand(0, 1)) { ctx.moveTo(sx, sy + ts - 2); ctx.lineTo(sx + ts, sy + ts - 2); }
    if (isLand(-1, 0)) { ctx.moveTo(sx + 2, sy); ctx.lineTo(sx + 2, sy + ts); }
    if (isLand(1, 0)) { ctx.moveTo(sx + ts - 2, sy); ctx.lineTo(sx + ts - 2, sy + ts); }
    ctx.stroke();
    // lily pad
    if (hash(x, y, 3) > .9) {
      const lx = sx + ts * (.3 + hash(x, y, 5) * .4), ly = sy + ts * .55;
      ctx.fillStyle = '#5faa6c';
      ctx.beginPath(); ctx.ellipse(lx, ly, ts * .11, ts * .07, .3, 0, 6.3); ctx.fill();
      ctx.fillStyle = '#ffd1e0';
      ctx.beginPath(); ctx.arc(lx + ts * .02, ly - ts * .01, ts * .025, 0, 6.3); ctx.fill();
    }
  }

  drawTree(ctx, sx, sy, ts, x, y) {
    const n = hash(x, y, 5);
    const cx = sx + ts * .5 + (n - .5) * ts * .1;
    const base = sy + ts * .92;
    const scale = .92 + n * .16;
    ctx.save();
    // shadow
    ctx.fillStyle = 'rgba(20, 58, 34, .22)';
    ctx.beginPath();
    ctx.ellipse(cx + ts * .05, base + ts * .02, ts * .34 * scale, ts * .12 * scale, 0, 0, 6.3);
    ctx.fill();
    // trunk
    ctx.fillStyle = '#7b5539';
    ctx.beginPath();
    ctx.moveTo(cx - ts * .06, base);
    ctx.quadraticCurveTo(cx - ts * .04, base - ts * .3, cx - ts * .03, base - ts * .45);
    ctx.lineTo(cx + ts * .03, base - ts * .45);
    ctx.quadraticCurveTo(cx + ts * .04, base - ts * .3, cx + ts * .06, base);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(50, 70, 40, .22)';
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(cx - ts * .015, base - ts * .05); ctx.lineTo(cx - ts * .01, base - ts * .4); ctx.stroke();
    // canopy — layered blobs
    const sway = Math.sin(this.time * 1.1 + x * .5 + y) * ts * .015;
    const cy = base - ts * .72;
    const r = ts * .42 * scale;
    const blobs = [
      [cx + sway, cy, r, '#2f7d4b'],
      [cx - r * .52 + sway, cy + r * .2, r * .68, '#358a53'],
      [cx + r * .55 + sway, cy + r * .16, r * .62, '#2b7447'],
      [cx - r * .2 + sway, cy - r * .46, r * .6, '#439c5e'],
      [cx + r * .22 + sway, cy - r * .5, r * .52, '#4aa866'],
    ];
    for (const [bx, by, br, col] of blobs) {
      ctx.fillStyle = col;
      ctx.beginPath(); ctx.arc(bx, by, br, 0, 6.3); ctx.fill();
    }
    // highlights
    ctx.fillStyle = 'rgba(163, 229, 150, .36)';
    ctx.beginPath(); ctx.ellipse(cx - r * .25 + sway, cy - r * .45, r * .32, r * .2, -.6, 0, 6.3); ctx.fill();
    if (n > .86) {
      ctx.fillStyle = 'rgba(255, 194, 214, .8)';
      for (let i = 0; i < 4; i++) {
        ctx.beginPath();
        ctx.arc(cx + Math.cos(i * 1.7) * r * .55 + sway, cy + Math.sin(i * 1.7) * r * .4, ts * .022, 0, 6.3);
        ctx.fill();
      }
    }
    ctx.restore();
  }

  drawRock(ctx, sx, sy, ts, x, y) {
    const n = hash(x, y, 2);
    ctx.fillStyle = 'rgba(20, 58, 34, .2)';
    ctx.beginPath(); ctx.ellipse(sx + ts * .5, sy + ts * .72, ts * .3, ts * .11, 0, 0, 6.3); ctx.fill();
    ctx.fillStyle = n > .5 ? '#9aa39a' : '#8d968e';
    ctx.beginPath();
    ctx.ellipse(sx + ts * .5, sy + ts * .55, ts * .28, ts * .22, n * .4, 0, 6.3);
    ctx.fill();
    ctx.fillStyle = 'rgba(230, 238, 226, .34)';
    ctx.beginPath();
    ctx.ellipse(sx + ts * .42, sy + ts * .46, ts * .13, ts * .075, -.4, 0, 6.3);
    ctx.fill();
    ctx.fillStyle = 'rgba(60, 80, 62, .3)';
    ctx.beginPath(); ctx.arc(sx + ts * .6, sy + ts * .62, ts * .025, 0, 6.3); ctx.fill();
  }

  /* ───────────────── buildings ───────────────── */

  drawBuilding(ctx, b, ox, oy, ts) {
    const bx = ox + b.x * ts;
    const bw = b.w * ts;
    const baseY = oy + (b.y + b.h) * ts;
    const wallH = Math.min(b.h * ts * .92, ts * 2.25);
    const roofH = ts * (b.kind === 'shop' ? .78 : 1.02);
    const wallTop = baseY - wallH;
    const roofTop = wallTop - roofH;
    const doorW = ts * .52;
    const doorH = ts * .92;
    const doorX = bx + bw / 2 - doorW / 2;
    const doorY = baseY - doorH;

    ctx.save();
    // ground shadow
    ctx.fillStyle = 'rgba(18, 52, 31, .24)';
    ctx.beginPath();
    ctx.ellipse(bx + bw / 2, baseY + ts * .04, bw * .52, ts * .16, 0, 0, 6.3);
    ctx.fill();

    // wall
    ctx.fillStyle = b.wall || '#f4e5c8';
    ctx.strokeStyle = 'rgba(92, 70, 47, .35)';
    ctx.lineWidth = Math.max(1.5, ts * .03);
    roundRect(ctx, bx + ts * .06, wallTop, bw - ts * .12, wallH, ts * .08);
    ctx.fill(); ctx.stroke();

    // wall texture
    ctx.strokeStyle = 'rgba(150, 118, 76, .13)';
    ctx.lineWidth = 1;
    for (let i = 0; i < 3; i++) {
      const yy = wallTop + wallH * (.3 + i * .2);
      ctx.beginPath(); ctx.moveTo(bx + ts * .12, yy); ctx.lineTo(bx + bw - ts * .12, yy); ctx.stroke();
    }

    // beams
    ctx.fillStyle = 'rgba(120, 86, 54, .32)';
    ctx.fillRect(bx + ts * .08, wallTop, ts * .06, wallH);
    ctx.fillRect(bx + bw - ts * .14, wallTop, ts * .06, wallH);

    // roof
    const roofColor = b.roof || '#c86858';
    ctx.fillStyle = roofColor;
    ctx.strokeStyle = 'rgba(60, 40, 30, .25)';
    ctx.lineWidth = Math.max(1.5, ts * .03);
    ctx.beginPath();
    ctx.moveTo(bx - ts * .08, wallTop + 2);
    ctx.quadraticCurveTo(bx + bw * .18, roofTop + roofH * .1, bx + bw * .5, roofTop);
    ctx.quadraticCurveTo(bx + bw * .82, roofTop + roofH * .1, bx + bw + ts * .08, wallTop + 2);
    ctx.lineTo(bx + bw + ts * .04, wallTop + ts * .14);
    ctx.quadraticCurveTo(bx + bw * .8, roofTop + roofH * .28, bx + bw * .5, roofTop + roofH * .30);
    ctx.quadraticCurveTo(bx + bw * .2, roofTop + roofH * .28, bx - ts * .04, wallTop + ts * .14);
    ctx.closePath();
    ctx.fill(); ctx.stroke();

    // shingles / roof highlights
    ctx.strokeStyle = 'rgba(255, 255, 255, .18)';
    ctx.lineWidth = 1;
    for (let i = 1; i < 4; i++) {
      const yy = wallTop - roofH * (i / 5);
      ctx.beginPath();
      ctx.moveTo(bx + bw * (.08 + i * .04), yy);
      ctx.quadraticCurveTo(bx + bw * .5, yy - roofH * .12, bx + bw * (.92 - i * .04), yy);
      ctx.stroke();
    }
    ctx.fillStyle = 'rgba(255, 255, 255, .25)';
    ctx.beginPath();
    ctx.ellipse(bx + bw * .32, roofTop + roofH * .28, bw * .18, ts * .06, -.2, 0, 6.3);
    ctx.fill();

    if (b.kind === 'cottage' || b.kind === 'inn' || b.kind === 'cabin') {
      // chimney
      ctx.fillStyle = '#9d8272';
      ctx.fillRect(bx + bw * .73, roofTop + roofH * .18, ts * .17, ts * .28);
      ctx.fillStyle = '#c7b3a0';
      ctx.fillRect(bx + bw * .73, roofTop + roofH * .18, ts * .17, ts * .06);
      // smoke
      ctx.fillStyle = 'rgba(255,255,255,.35)';
      for (let i = 0; i < 3; i++) {
        const sy = roofTop - i * ts * .17 + Math.sin(this.time * 1.2 + i) * ts * .02;
        ctx.beginPath();
        ctx.arc(bx + bw * .815 + i * ts * .04, sy, ts * (.04 + i * .012), 0, 6.3);
        ctx.fill();
      }
    }

    if (b.kind === 'shop') {
      // striped awning
      const ay = wallTop + ts * .16;
      const ay2 = wallTop + ts * .48;
      ctx.save();
      ctx.beginPath(); ctx.rect(bx + ts * .04, ay, bw - ts * .08, ay2 - ay); ctx.clip();
      for (let i = 0; i < 7; i++) {
        ctx.fillStyle = i % 2 ? '#fff2d0' : '#e5895b';
        const sw = (bw - ts * .08) / 7;
        ctx.fillRect(bx + ts * .04 + i * sw, ay, sw + 1, ay2 - ay);
      }
      ctx.restore();
      ctx.beginPath();
      ctx.moveTo(bx + ts * .02, ay2);
      for (let i = 0; i < 7; i++) {
        const sw = (bw - ts * .04) / 7;
        const xx = bx + ts * .02 + i * sw;
        ctx.quadraticCurveTo(xx + sw * .5, ay2 + ts * .13, xx + sw, ay2);
      }
      ctx.closePath();
      ctx.fillStyle = 'rgba(229, 137, 91, .55)';
      ctx.fill();
    }

    if (b.kind === 'hall') {
      // clock / emblem
      ctx.fillStyle = '#ffe9a8';
      ctx.beginPath(); ctx.arc(bx + bw / 2, wallTop + wallH * .18, ts * .18, 0, 6.3); ctx.fill();
      ctx.strokeStyle = '#7d6bb0'; ctx.lineWidth = Math.max(1.4, ts * .03);
      ctx.beginPath(); ctx.arc(bx + bw / 2, wallTop + wallH * .18, ts * .18, 0, 6.3); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(bx + bw / 2, wallTop + wallH * .18); ctx.lineTo(bx + bw / 2, wallTop + wallH * .18 - ts * .1); ctx.moveTo(bx + bw / 2, wallTop + wallH * .18); ctx.lineTo(bx + bw / 2 + ts * .07, wallTop + wallH * .18 + ts * .03); ctx.stroke();
    }

    if (b.kind === 'shrine') {
      // second tier
      const t2 = roofTop - roofH * .32;
      ctx.fillStyle = '#4f8464';
      ctx.beginPath();
      ctx.moveTo(bx - ts * .22, roofTop + roofH * .18);
      ctx.quadraticCurveTo(bx + bw * .5, t2 - ts * .2, bx + bw + ts * .22, roofTop + roofH * .18);
      ctx.lineTo(bx + bw + ts * .12, roofTop + roofH * .34);
      ctx.quadraticCurveTo(bx + bw * .5, t2 + ts * .12, bx - ts * .12, roofTop + roofH * .34);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = '#f0d883'; ctx.lineWidth = Math.max(1.5, ts * .028); ctx.stroke();
      // lanterns
      for (const side of [-1, 1]) {
        const lx = bx + bw / 2 + side * (bw * .34);
        const ly = wallTop + ts * .2;
        ctx.fillStyle = '#ffdf8a';
        ctx.beginPath(); ctx.arc(lx, ly, ts * .075, 0, 6.3); ctx.fill();
        ctx.strokeStyle = '#7d6b43'; ctx.lineWidth = 2;
        ctx.beginPath(); ctx.moveTo(lx, ly - ts * .1); ctx.lineTo(lx, ly - ts * .18); ctx.stroke();
        ctx.fillStyle = 'rgba(255, 223, 138, .28)';
        ctx.beginPath(); ctx.arc(lx, ly, ts * .15, 0, 6.3); ctx.fill();
      }
      // hanging banner
      ctx.fillStyle = '#d45d86';
      ctx.fillRect(bx + bw * .5 - ts * .12, wallTop + ts * .34, ts * .24, ts * .38);
      ctx.fillStyle = '#ffe9a8';
      ctx.beginPath(); ctx.arc(bx + bw * .5, wallTop + ts * .52, ts * .045, 0, 6.3); ctx.fill();
    }

    // windows
    const winY = wallTop + wallH * .34;
    const winW = ts * .34, winH = ts * .3;
    const winXs = b.kind === 'shop' ? [bx + bw * .2, bx + bw * .62] : [bx + bw * .22, bx + bw * .64];
    for (const wx of winXs) {
      const wy = b.kind === 'shop' ? wallTop + wallH * .58 : winY;
      ctx.fillStyle = '#5b87a0';
      roundRect(ctx, wx, wy, winW, winH, ts * .04);
      ctx.fill();
      ctx.strokeStyle = 'rgba(255, 248, 218, .8)'; ctx.lineWidth = Math.max(1.2, ts * .024); ctx.stroke();
      ctx.fillStyle = 'rgba(255, 244, 186, .55)';
      ctx.fillRect(wx + winW * .1, wy + winH * .12, winW * .32, winH * .3);
      ctx.strokeStyle = 'rgba(255, 248, 218, .7)'; ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(wx + winW / 2, wy); ctx.lineTo(wx + winW / 2, wy + winH); ctx.moveTo(wx, wy + winH / 2); ctx.lineTo(wx + winW, wy + winH / 2); ctx.stroke();
    }

    // door
    ctx.fillStyle = '#7a5537';
    roundRect(ctx, doorX, doorY, doorW, doorH, ts * .06);
    ctx.fill();
    ctx.strokeStyle = 'rgba(255, 238, 200, .28)'; ctx.lineWidth = 1.4; ctx.stroke();
    ctx.fillStyle = 'rgba(255, 238, 200, .22)';
    ctx.fillRect(doorX + doorW * .16, doorY + doorH * .12, doorW * .68, doorH * .28);
    ctx.fillStyle = '#ffd166';
    ctx.beginPath(); ctx.arc(doorX + doorW * .8, doorY + doorH * .58, ts * .035, 0, 6.3); ctx.fill();
    // step
    ctx.fillStyle = 'rgba(180, 160, 120, .8)';
    ctx.fillRect(doorX - ts * .08, baseY - ts * .03, doorW + ts * .16, ts * .06);

    // flower boxes
    if (b.kind !== 'shrine') {
      ctx.fillStyle = '#8a5f3f';
      ctx.fillRect(bx + bw * .14, winY + winH + ts * .02, winW, ts * .06);
      const cols = ['#ff9ab8', '#ffd166', '#ffb3d1'];
      for (let i = 0; i < 4; i++) {
        ctx.fillStyle = cols[i % cols.length];
        ctx.beginPath();
        ctx.arc(bx + bw * .14 + winW * (.15 + i * .23), winY + winH + ts * .005, ts * .026, 0, 6.3);
        ctx.fill();
      }
    }

    // name plaque for shop/hall
    if (b.kind === 'shop' || b.kind === 'hall') {
      ctx.fillStyle = 'rgba(255, 249, 227, .88)';
      roundRect(ctx, bx + bw * .5 - ts * .52, wallTop + wallH * .08, ts * 1.04, ts * .17, ts * .05);
      ctx.fill();
      ctx.fillStyle = '#7a5537';
      ctx.font = `700 ${Math.max(6, ts * .11)}px "Trebuchet MS", sans-serif`;
      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.fillText(b.name.replace('Lumen Hall', 'LUMEN HALL').replace("Pip's Petals", "PIP'S"), bx + bw * .5, wallTop + wallH * .16);
    }
    ctx.restore();
  }

  /* ───────────────── props ───────────────── */

  drawProp(ctx, p, ox, oy, ts) {
    const cx = ox + p.x * ts + ts / 2;
    const cy = oy + p.y * ts + ts / 2;
    if (p.kind === 'fountain') return this.drawFountain(ctx, cx, cy, ts);
    if (p.kind === 'moonwell') return this.drawMoonwell(ctx, cx, cy, ts);
    if (p.kind === 'gate') return this.drawGate(ctx, p, ox, oy, ts);
    if (p.kind === 'altar') return this.drawAltar(ctx, cx, cy, ts);
  }

  drawFountain(ctx, cx, cy, ts) {
    const r = ts * .52;
    ctx.save();
    ctx.fillStyle = 'rgba(18, 52, 31, .22)';
    ctx.beginPath(); ctx.ellipse(cx, cy + ts * .26, r * 1.05, ts * .12, 0, 0, 6.3); ctx.fill();
    // base
    ctx.fillStyle = '#aab5a5';
    ctx.beginPath(); ctx.ellipse(cx, cy + ts * .2, r, r * .46, 0, 0, 6.3); ctx.fill();
    ctx.fillStyle = '#c4cdbb';
    ctx.beginPath(); ctx.ellipse(cx, cy + ts * .13, r, r * .45, 0, 0, 6.3); ctx.fill();
    // water
    const waterGrad = ctx.createRadialGradient(cx - r * .2, cy, r * .1, cx, cy, r);
    waterGrad.addColorStop(0, '#a9f0e8');
    waterGrad.addColorStop(.7, '#59c3cf');
    waterGrad.addColorStop(1, '#338fa9');
    ctx.fillStyle = waterGrad;
    ctx.beginPath(); ctx.ellipse(cx, cy + ts * .1, r * .8, r * .32, 0, 0, 6.3); ctx.fill();
    // ripples
    ctx.strokeStyle = 'rgba(255,255,255,.45)'; ctx.lineWidth = 1.2;
    for (let i = 0; i < 2; i++) {
      const ph = (this.time * .5 + i * .5) % 1;
      ctx.globalAlpha = 1 - ph;
      ctx.beginPath(); ctx.ellipse(cx, cy + ts * .1, r * .2 + r * .55 * ph, (r * .08 + r * .22 * ph), 0, 0, 6.3); ctx.stroke();
    }
    ctx.globalAlpha = 1;
    // center statue
    ctx.fillStyle = '#8e9b8d';
    ctx.fillRect(cx - ts * .035, cy - ts * .3, ts * .07, ts * .42);
    ctx.fillStyle = '#b8c6b4';
    ctx.beginPath(); ctx.arc(cx, cy - ts * .34, ts * .09, 0, 6.3); ctx.fill();
    // little bloom
    ctx.fillStyle = '#ffc2d4';
    for (let i = 0; i < 5; i++) {
      ctx.beginPath(); ctx.arc(cx + Math.cos(i * 1.256) * ts * .07, cy - ts * .34 + Math.sin(i * 1.256) * ts * .07, ts * .035, 0, 6.3); ctx.fill();
    }
    ctx.fillStyle = '#ffd166'; ctx.beginPath(); ctx.arc(cx, cy - ts * .34, ts * .032, 0, 6.3); ctx.fill();
    // sparkle
    ctx.fillStyle = 'rgba(255, 247, 190, .9)';
    const sp = Math.sin(this.time * 2) * .5 + .5;
    ctx.beginPath(); ctx.arc(cx + r * .5, cy - ts * .02, 1.5 + sp * 1.5, 0, 6.3); ctx.fill();
    ctx.restore();
  }

  drawMoonwell(ctx, cx, cy, ts) {
    const r = ts * .5;
    ctx.save();
    ctx.fillStyle = 'rgba(12, 36, 28, .3)';
    ctx.beginPath(); ctx.ellipse(cx, cy + ts * .24, r * 1.08, ts * .13, 0, 0, 6.3); ctx.fill();
    ctx.fillStyle = '#7f9285';
    ctx.beginPath(); ctx.ellipse(cx, cy + ts * .16, r, r * .5, 0, 0, 6.3); ctx.fill();
    ctx.fillStyle = '#9db4a1';
    ctx.beginPath(); ctx.ellipse(cx, cy + ts * .08, r * .92, r * .44, 0, 0, 6.3); ctx.fill();
    const g = ctx.createRadialGradient(cx, cy + ts * .03, 2, cx, cy + ts * .03, r * .8);
    g.addColorStop(0, '#d8fbff'); g.addColorStop(.45, '#7adbe8'); g.addColorStop(1, '#2e7e9f');
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.ellipse(cx, cy + ts * .03, r * .74, r * .31, 0, 0, 6.3); ctx.fill();
    // moon reflection
    ctx.fillStyle = 'rgba(255, 249, 216, .8)';
    ctx.beginPath(); ctx.arc(cx + Math.sin(this.time * .5) * ts * .06, cy + ts * .02, ts * .09, 0, 6.3); ctx.fill();
    ctx.fillStyle = 'rgba(46,126,159,.55)';
    ctx.beginPath(); ctx.arc(cx + Math.sin(this.time * .5) * ts * .06 + ts * .035, cy + ts * .005, ts * .07, 0, 6.3); ctx.fill();
    // runes
    ctx.strokeStyle = 'rgba(230, 255, 255, .4)'; ctx.lineWidth = 1;
    for (let i = 0; i < 3; i++) {
      const a = this.time * .4 + i * 2.1;
      ctx.beginPath(); ctx.arc(cx + Math.cos(a) * r * .85, cy + ts * .12 + Math.sin(a) * r * .35, 1.6, 0, 6.3); ctx.stroke();
    }
    // stone posts
    for (const side of [-1, 1]) {
      ctx.fillStyle = '#7b8d7f';
      ctx.fillRect(cx + side * r * .9 - ts * .045, cy - ts * .18, ts * .09, ts * .34);
      ctx.fillStyle = '#a4b6a6';
      ctx.fillRect(cx + side * r * .9 - ts * .05, cy - ts * .21, ts * .1, ts * .06);
    }
    ctx.restore();
  }

  drawGate(ctx, p, ox, oy, ts) {
    const cx = ox + p.x * ts + ts / 2;
    const by = oy + p.y * ts + ts * .92;
    const open = this.state.flags.gateOpened;
    ctx.save();
    ctx.fillStyle = 'rgba(18, 52, 31, .25)';
    ctx.beginPath(); ctx.ellipse(cx, by, ts * .8, ts * .16, 0, 0, 6.3); ctx.fill();
    // pillars
    for (const side of [-1, 1]) {
      const px = cx + side * ts * .46;
      ctx.fillStyle = '#8e9c8a';
      roundRect(ctx, px - ts * .1, by - ts * 1.45, ts * .2, ts * 1.42, ts * .04);
      ctx.fill();
      ctx.fillStyle = '#b6c4b0';
      ctx.fillRect(px - ts * .13, by - ts * 1.55, ts * .26, ts * .13);
      ctx.fillStyle = '#6f7f6d';
      ctx.fillRect(px - ts * .12, by - ts * .08, ts * .24, ts * .1);
      ctx.fillStyle = 'rgba(255, 233, 168, .8)';
      ctx.beginPath(); ctx.arc(px, by - ts * 1.16, ts * .035, 0, 6.3); ctx.fill();
    }
    // arch
    ctx.strokeStyle = '#8e9c8a';
    ctx.lineWidth = ts * .11;
    ctx.beginPath(); ctx.arc(cx, by - ts * 1.42, ts * .55, Math.PI, 0); ctx.stroke();
    ctx.strokeStyle = '#b6c4b0';
    ctx.lineWidth = ts * .035;
    ctx.beginPath(); ctx.arc(cx, by - ts * 1.46, ts * .56, Math.PI, 0); ctx.stroke();
    // seal sockets
    const n = this.game.sealCount();
    for (let i = 0; i < 3; i++) {
      const sx = cx + (i - 1) * ts * .24;
      ctx.fillStyle = i < n ? '#ffd166' : 'rgba(255,255,255,.18)';
      ctx.beginPath(); ctx.arc(sx, by - ts * 1.52, ts * .045, 0, 6.3); ctx.fill();
      if (i < n) {
        ctx.fillStyle = 'rgba(255, 209, 102, .3)';
        ctx.beginPath(); ctx.arc(sx, by - ts * 1.52, ts * .09, 0, 6.3); ctx.fill();
      }
    }
    if (!open) {
      // shimmer barrier
      const gl = ctx.createLinearGradient(cx, by - ts * 1.4, cx, by);
      gl.addColorStop(0, 'rgba(160, 240, 220, .05)');
      gl.addColorStop(.5, 'rgba(160, 240, 220, .22)');
      gl.addColorStop(1, 'rgba(160, 240, 220, .06)');
      ctx.fillStyle = gl;
      ctx.fillRect(cx - ts * .42, by - ts * 1.4, ts * .84, ts * 1.4);
      ctx.strokeStyle = 'rgba(210, 255, 240, .45)';
      ctx.lineWidth = 1.4;
      for (let i = 0; i < 4; i++) {
        const yy = by - ts * .2 - ((this.time * 18 + i * 34) % (ts * 1.2));
        ctx.beginPath(); ctx.moveTo(cx - ts * .38, yy); ctx.lineTo(cx + ts * .38, yy - ts * .05); ctx.stroke();
      }
      ctx.fillStyle = 'rgba(10, 40, 28, .72)';
      roundRect(ctx, cx - ts * .42, by - ts * .68, ts * .84, ts * .2, ts * .05);
      ctx.fill();
      ctx.fillStyle = '#ffe9a8';
      ctx.font = `900 ${Math.max(6, ts * .095)}px "Trebuchet MS", sans-serif`;
      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.fillText(`${n} / 3 SEALS`, cx, by - ts * .575);
    } else {
      ctx.fillStyle = 'rgba(255, 233, 168, .18)';
      ctx.beginPath(); ctx.ellipse(cx, by, ts * .6, ts * .2, 0, 0, 6.3); ctx.fill();
    }
    ctx.restore();
  }

  drawAltar(ctx, cx, cy, ts) {
    ctx.save();
    const glow = .5 + Math.sin(this.time * 1.6) * .15;
    ctx.fillStyle = `rgba(255, 226, 140, ${.16 + glow * .15})`;
    ctx.beginPath(); ctx.arc(cx, cy - ts * .3, ts * .55, 0, 6.3); ctx.fill();
    ctx.fillStyle = 'rgba(18, 52, 31, .25)';
    ctx.beginPath(); ctx.ellipse(cx, cy + ts * .3, ts * .46, ts * .12, 0, 0, 6.3); ctx.fill();
    // pedestal
    ctx.fillStyle = '#a4b09c';
    ctx.beginPath();
    ctx.moveTo(cx - ts * .25, cy + ts * .3);
    ctx.lineTo(cx - ts * .18, cy - ts * .1);
    ctx.lineTo(cx + ts * .18, cy - ts * .1);
    ctx.lineTo(cx + ts * .25, cy + ts * .3);
    ctx.closePath(); ctx.fill();
    ctx.fillStyle = '#c3cdb8';
    ctx.fillRect(cx - ts * .3, cy + ts * .25, ts * .6, ts * .08);
    ctx.fillStyle = '#fff3b8';
    ctx.beginPath(); ctx.arc(cx, cy - ts * .42 + Math.sin(this.time * 1.6) * ts * .03, ts * .1, 0, 6.3); ctx.fill();
    ctx.fillStyle = '#ffb3c8';
    for (let i = 0; i < 6; i++) {
      const a = i / 6 * 6.283 + this.time * .2;
      ctx.beginPath(); ctx.arc(cx + Math.cos(a) * ts * .15, cy - ts * .42 + Math.sin(a) * ts * .15, ts * .06, 0, 6.3); ctx.fill();
    }
    ctx.fillStyle = '#ffd166';
    ctx.beginPath(); ctx.arc(cx, cy - ts * .42, ts * .075, 0, 6.3); ctx.fill();
    ctx.restore();
  }

  drawSign(ctx, s, ox, oy, ts) {
    const cx = ox + s.x * ts + ts / 2;
    const by = oy + s.y * ts + ts * .88;
    ctx.save();
    ctx.fillStyle = 'rgba(18, 52, 31, .2)';
    ctx.beginPath(); ctx.ellipse(cx, by, ts * .24, ts * .07, 0, 0, 6.3); ctx.fill();
    ctx.fillStyle = '#8a6244';
    ctx.fillRect(cx - ts * .035, by - ts * .48, ts * .07, ts * .5);
    ctx.fillStyle = '#b48558';
    roundRect(ctx, cx - ts * .27, by - ts * .82, ts * .54, ts * .38, ts * .05);
    ctx.fill();
    ctx.strokeStyle = '#7b5335'; ctx.lineWidth = 2; ctx.stroke();
    ctx.strokeStyle = 'rgba(110, 78, 50, .5)'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(cx - ts * .18, by - ts * .71); ctx.lineTo(cx + ts * .17, by - ts * .71); ctx.moveTo(cx - ts * .18, by - ts * .62); ctx.lineTo(cx + ts * .1, by - ts * .62); ctx.stroke();
    ctx.restore();
  }

  /* ───────────────── characters ───────────────── */

  drawNPC(ctx, n, ox, oy, ts) {
    const cx = ox + n.x * ts + ts / 2;
    const by = oy + n.y * ts + ts * .94;
    const done = n.trainer && this.state.flags.defeated[n.trainer];
    const bob = Math.sin(this.time * 2 + n.x) * ts * .012;
    this.drawPerson(ctx, cx, by + bob, ts * (n.trainer ? .95 : .88), {
      hair: n.hair, dress: n.dress, dir: n.dir || 'down',
      scarf: n.portrait === 'queen' ? '#ffd166' : null,
      queen: n.portrait === 'queen',
    });
    // marker
    if (n.trainer && !done) {
      const my = by - ts * 1.28 + Math.sin(this.time * 3) * 3;
      ctx.fillStyle = 'rgba(20, 50, 35, .18)';
      ctx.beginPath(); ctx.arc(cx, my, ts * .15, 0, 6.3); ctx.fill();
      ctx.fillStyle = '#ffe08a';
      ctx.beginPath(); ctx.arc(cx, my, ts * .13, 0, 6.3); ctx.fill();
      ctx.fillStyle = '#6b4511';
      ctx.font = `900 ${Math.round(ts * .18)}px "Trebuchet MS", sans-serif`;
      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.fillText('!', cx, my + 1);
    } else if (n.shop) {
      const my = by - ts * 1.26 + Math.sin(this.time * 3 + 1) * 2;
      ctx.fillStyle = '#ffe08a';
      ctx.beginPath(); ctx.arc(cx, my, ts * .13, 0, 6.3); ctx.fill();
      ctx.fillStyle = '#6b4511';
      ctx.font = `900 ${Math.round(ts * .17)}px "Trebuchet MS", sans-serif`;
      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.fillText('$', cx, my + 1);
    } else if (n.portrait === 'queen') {
      const my = by - ts * 1.35;
      ctx.fillStyle = '#ffe08a';
      ctx.beginPath();
      ctx.moveTo(cx - ts * .13, my + ts * .06);
      ctx.lineTo(cx - ts * .15, my - ts * .08);
      ctx.lineTo(cx - ts * .06, my - ts * .02);
      ctx.lineTo(cx, my - ts * .12);
      ctx.lineTo(cx + ts * .06, my - ts * .02);
      ctx.lineTo(cx + ts * .15, my - ts * .08);
      ctx.lineTo(cx + ts * .13, my + ts * .06);
      ctx.closePath(); ctx.fill();
    }
  }

  drawPerson(ctx, cx, by, s, opts) {
    const hair = opts.hair || '#7a5a44';
    const dress = opts.dress || '#6f8a72';
    const dir = opts.dir || 'down';
    const skin = '#f5c9a9';
    ctx.save();
    // shadow
    ctx.fillStyle = 'rgba(18, 52, 31, .24)';
    ctx.beginPath(); ctx.ellipse(cx, by, s * .32, s * .1, 0, 0, 6.3); ctx.fill();
    // legs
    ctx.fillStyle = '#5f4a3a';
    ctx.fillRect(cx - s * .13, by - s * .28, s * .1, s * .26);
    ctx.fillRect(cx + s * .03, by - s * .28, s * .1, s * .26);
    // body
    ctx.fillStyle = dress;
    ctx.beginPath();
    ctx.moveTo(cx - s * .2, by - s * .65);
    ctx.quadraticCurveTo(cx - s * .26, by - s * .4, cx - s * .23, by - s * .25);
    ctx.lineTo(cx + s * .23, by - s * .25);
    ctx.quadraticCurveTo(cx + s * .26, by - s * .4, cx + s * .2, by - s * .65);
    ctx.closePath(); ctx.fill();
    // sash
    ctx.fillStyle = 'rgba(255, 250, 220, .5)';
    ctx.fillRect(cx - s * .2, by - s * .42, s * .4, s * .07);
    // arms
    ctx.fillStyle = skin;
    ctx.beginPath(); ctx.arc(cx - s * .23, by - s * .4, s * .055, 0, 6.3); ctx.fill();
    ctx.beginPath(); ctx.arc(cx + s * .23, by - s * .4, s * .055, 0, 6.3); ctx.fill();
    // head
    ctx.fillStyle = skin;
    ctx.beginPath(); ctx.arc(cx, by - s * .86, s * .22, 0, 6.3); ctx.fill();
    // hair
    ctx.fillStyle = hair;
    ctx.beginPath();
    ctx.arc(cx, by - s * .92, s * .235, Math.PI * .95, Math.PI * 2.05);
    ctx.lineTo(cx + s * .22, by - s * .78);
    ctx.quadraticCurveTo(cx + s * .12, by - s * .88, cx, by - s * .86);
    ctx.quadraticCurveTo(cx - s * .12, by - s * .88, cx - s * .22, by - s * .78);
    ctx.closePath(); ctx.fill();
    // side locks
    ctx.beginPath(); ctx.ellipse(cx - s * .22, by - s * .82, s * .05, s * .13, 0, 0, 6.3); ctx.fill();
    ctx.beginPath(); ctx.ellipse(cx + s * .22, by - s * .82, s * .05, s * .13, 0, 0, 6.3); ctx.fill();
    // face
    if (dir !== 'up') {
      ctx.fillStyle = '#3a2a2a';
      const ex = dir === 'left' ? -.07 : dir === 'right' ? .07 : 0;
      if (dir === 'left' || dir === 'right') {
        ctx.beginPath(); ctx.arc(cx + ex * s * 1.6, by - s * .85, s * .024, 0, 6.3); ctx.fill();
      } else {
        ctx.beginPath(); ctx.arc(cx - s * .075, by - s * .85, s * .025, 0, 6.3); ctx.fill();
        ctx.beginPath(); ctx.arc(cx + s * .075, by - s * .85, s * .025, 0, 6.3); ctx.fill();
      }
      ctx.fillStyle = 'rgba(255, 147, 170, .45)';
      ctx.beginPath(); ctx.arc(cx - s * .14, by - s * .8, s * .035, 0, 6.3); ctx.fill();
      ctx.beginPath(); ctx.arc(cx + s * .14, by - s * .8, s * .035, 0, 6.3); ctx.fill();
    }
    // scarf / cape
    if (opts.scarf) {
      ctx.fillStyle = opts.scarf;
      roundRect(ctx, cx - s * .18, by - s * .68, s * .36, s * .1, s * .05);
      ctx.fill();
    }
    if (opts.queen) {
      ctx.fillStyle = 'rgba(255, 209, 102, .3)';
      ctx.beginPath();
      ctx.moveTo(cx - s * .22, by - s * .66);
      ctx.lineTo(cx - s * .38, by - s * .22);
      ctx.lineTo(cx + s * .38, by - s * .22);
      ctx.lineTo(cx + s * .22, by - s * .66);
      ctx.closePath(); ctx.fill();
    }
    ctx.restore();
  }

  drawPlayer(ctx, ox, oy, ts) {
    const cx = ox + this.vx * ts + ts / 2;
    const by = oy + this.vy * ts + ts * .94;
    const moving = this.moving;
    const bob = moving ? Math.abs(Math.sin(this.walkPhase)) * -ts * .035 : Math.sin(this.time * 2.4) * ts * .008;
    const legSwing = moving ? Math.sin(this.walkPhase) * ts * .07 : 0;
    const dir = this.dir;
    const s = ts * .92;
    ctx.save();
    // shadow
    ctx.fillStyle = 'rgba(18, 52, 31, .25)';
    ctx.beginPath(); ctx.ellipse(cx + this.bump * (dir === 'left' ? 3 : dir === 'right' ? -3 : 0), by, s * .33, s * .105, 0, 0, 6.3); ctx.fill();
    ctx.translate(cx, by + bob);
    if (this.bump > 0) ctx.translate(dir === 'left' ? -this.bump * 3 : dir === 'right' ? this.bump * 3 : 0, dir === 'up' ? -this.bump * 2 : this.bump * 2);
    // legs
    ctx.strokeStyle = '#5d4a3c';
    ctx.lineWidth = s * .1;
    ctx.lineCap = 'round';
    ctx.beginPath(); ctx.moveTo(-s * .09, -s * .28); ctx.lineTo(-s * .09 + legSwing, -s * .03); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(s * .09, -s * .28); ctx.lineTo(s * .09 - legSwing, -s * .03); ctx.stroke();
    // boots
    ctx.fillStyle = '#43352c';
    ctx.beginPath(); ctx.ellipse(-s * .09 + legSwing, -s * .02, s * .075, s * .035, 0, 0, 6.3); ctx.fill();
    ctx.beginPath(); ctx.ellipse(s * .09 - legSwing, -s * .02, s * .075, s * .035, 0, 0, 6.3); ctx.fill();
    // backpack behind
    if (dir === 'up') {
      ctx.fillStyle = '#9a6a3f';
      roundRect(ctx, -s * .16, -s * .65, s * .32, s * .3, s * .06); ctx.fill();
      ctx.fillStyle = '#c18b58';
      roundRect(ctx, -s * .12, -s * .61, s * .24, s * .12, s * .04); ctx.fill();
    }
    // body (green tunic)
    ctx.fillStyle = '#4fae72';
    ctx.beginPath();
    ctx.moveTo(-s * .19, -s * .66);
    ctx.quadraticCurveTo(-s * .24, -s * .4, -s * .2, -s * .26);
    ctx.lineTo(s * .2, -s * .26);
    ctx.quadraticCurveTo(s * .24, -s * .4, s * .19, -s * .66);
    ctx.closePath(); ctx.fill();
    // belt
    ctx.fillStyle = '#7b5537';
    ctx.fillRect(-s * .19, -s * .44, s * .38, s * .06);
    ctx.fillStyle = '#ffd166';
    ctx.beginPath(); ctx.arc(0, -s * .41, s * .035, 0, 6.3); ctx.fill();
    // scarf
    ctx.fillStyle = '#f2a93b';
    roundRect(ctx, -s * .17, -s * .7, s * .34, s * .09, s * .04); ctx.fill();
    if (dir !== 'up') {
      ctx.beginPath();
      ctx.moveTo(s * .1, -s * .66);
      ctx.quadraticCurveTo(s * .28 + Math.sin(this.time * 4) * s * .03, -s * .55, s * .22, -s * .38);
      ctx.lineTo(s * .14, -s * .45);
      ctx.closePath(); ctx.fill();
    }
    // arms
    ctx.strokeStyle = '#f3c6a3'; ctx.lineWidth = s * .08;
    const armSwing = moving ? Math.sin(this.walkPhase + Math.PI) * s * .05 : 0;
    ctx.beginPath(); ctx.moveTo(-s * .18, -s * .61); ctx.lineTo(-s * .23, -s * .38 + armSwing); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(s * .18, -s * .61); ctx.lineTo(s * .23, -s * .38 - armSwing); ctx.stroke();
    // head
    ctx.fillStyle = '#f7ceac';
    ctx.beginPath(); ctx.arc(0, -s * .86, s * .215, 0, 6.3); ctx.fill();
    // hair
    ctx.fillStyle = '#5a4030';
    ctx.beginPath();
    ctx.arc(0, -s * .91, s * .23, Math.PI * .92, Math.PI * 2.08);
    ctx.lineTo(s * .21, -s * .78);
    ctx.quadraticCurveTo(s * .12, -s * .9, 0, -s * .88);
    ctx.quadraticCurveTo(-s * .12, -s * .9, -s * .21, -s * .78);
    ctx.closePath(); ctx.fill();
    // fringe
    ctx.beginPath();
    ctx.moveTo(-s * .2, -s * .84);
    ctx.quadraticCurveTo(-s * .1, -s * .74, 0, -s * .82);
    ctx.quadraticCurveTo(s * .1, -s * .74, s * .2, -s * .84);
    ctx.lineTo(s * .2, -s * .92);
    ctx.quadraticCurveTo(0, -s * 1.05, -s * .2, -s * .92);
    ctx.closePath(); ctx.fill();
    // hat / leaf
    ctx.fillStyle = '#7cbf5e';
    ctx.beginPath();
    ctx.ellipse(s * .12, -s * 1.04, s * .09, s * .045, -.5, 0, 6.3); ctx.fill();
    // face
    if (dir !== 'up') {
      ctx.fillStyle = '#3a2a2a';
      if (dir === 'left') {
        ctx.beginPath(); ctx.arc(-s * .11, -s * .85, s * .027, 0, 6.3); ctx.fill();
      } else if (dir === 'right') {
        ctx.beginPath(); ctx.arc(s * .11, -s * .85, s * .027, 0, 6.3); ctx.fill();
      } else {
        ctx.beginPath(); ctx.arc(-s * .08, -s * .85, s * .027, 0, 6.3); ctx.fill();
        ctx.beginPath(); ctx.arc(s * .08, -s * .85, s * .027, 0, 6.3); ctx.fill();
      }
      ctx.fillStyle = 'rgba(255, 147, 170, .45)';
      ctx.beginPath(); ctx.arc(-s * .14, -s * .79, s * .035, 0, 6.3); ctx.fill();
      ctx.beginPath(); ctx.arc(s * .14, -s * .79, s * .035, 0, 6.3); ctx.fill();
    }
    ctx.restore();
  }

  drawCompanion(ctx, ox, oy, ts) {
    const lead = this.state.party.find(c => c.hp > 0) || this.state.party[0];
    if (!lead) return;
    const sp = SPECIES[lead.species];
    const cx = ox + this.compX * ts + ts / 2;
    const by = oy + this.compY * ts + ts * .93;
    const adult = sp.stage > 1;
    const bob = Math.sin(this.time * 3 + 1) * ts * .012;
    const s = ts * (adult ? .74 : .62);
    const hair = sp.art.hairDark;
    const hairLight = sp.art.hair;
    const dress = sp.art.dressDark;
    ctx.save();
    ctx.fillStyle = 'rgba(18, 52, 31, .2)';
    ctx.beginPath(); ctx.ellipse(cx, by, s * .33, s * .1, 0, 0, 6.3); ctx.fill();
    ctx.translate(cx, by + bob);
    if (adult) {
      // long dress + slim body
      ctx.fillStyle = dress;
      ctx.beginPath();
      ctx.moveTo(-s * .16, -s * .66);
      ctx.quadraticCurveTo(-s * .13, -s * .38, -s * .24, -s * .15);
      ctx.lineTo(s * .24, -s * .15);
      ctx.quadraticCurveTo(s * .13, -s * .38, s * .16, -s * .66);
      ctx.closePath(); ctx.fill();
      ctx.fillStyle = '#f7ceac';
      ctx.fillRect(-s * .065, -s * .15, s * .05, s * .14);
      ctx.fillRect(s * .015, -s * .15, s * .05, s * .14);
      ctx.fillStyle = sp.art.trim || '#fff4d6';
      ctx.fillRect(-s * .22, -s * .28, s * .44, s * .035);
    } else {
      ctx.fillStyle = dress;
      ctx.beginPath();
      ctx.moveTo(-s * .18, -s * .55);
      ctx.quadraticCurveTo(-s * .24, -s * .3, -s * .2, -s * .13);
      ctx.lineTo(s * .2, -s * .13);
      ctx.quadraticCurveTo(s * .24, -s * .3, s * .18, -s * .55);
      ctx.closePath(); ctx.fill();
      ctx.fillStyle = '#f7ceac';
      ctx.fillRect(-s * .09, -s * .13, s * .06, s * .12);
      ctx.fillRect(s * .03, -s * .13, s * .06, s * .12);
    }
    // head
    ctx.fillStyle = '#f7ceac';
    ctx.beginPath(); ctx.arc(0, -s * (adult ? .75 : .69), s * (adult ? .18 : .23), 0, 6.3); ctx.fill();
    // hair
    ctx.fillStyle = hair;
    if (adult) {
      ctx.beginPath(); ctx.arc(0, -s * .79, s * .2, Math.PI * .92, Math.PI * 2.08); ctx.fill();
      ctx.fillRect(-s * .19, -s * .8, s * .07, s * .38);
      ctx.fillRect(s * .12, -s * .8, s * .07, s * .38);
    } else {
      ctx.beginPath(); ctx.arc(0, -s * .73, s * .25, Math.PI * .92, Math.PI * 2.08); ctx.fill();
      // twin tails
      ctx.beginPath(); ctx.ellipse(-s * .25, -s * .62, s * .06, s * .16, -.2, 0, 6.3); ctx.fill();
      ctx.beginPath(); ctx.ellipse(s * .25, -s * .62, s * .06, s * .16, .2, 0, 6.3); ctx.fill();
    }
    // fringe highlight
    ctx.fillStyle = hairLight;
    ctx.beginPath(); ctx.arc(-s * .05, -s * (adult ? .87 : .83), s * .09, Math.PI * .9, Math.PI * 1.8); ctx.fill();
    // eyes
    ctx.fillStyle = '#3a2a2a';
    const ey = -s * (adult ? .76 : .7);
    ctx.beginPath(); ctx.arc(-s * .065, ey, s * .026, 0, 6.3); ctx.fill();
    ctx.beginPath(); ctx.arc(s * .065, ey, s * .026, 0, 6.3); ctx.fill();
    ctx.fillStyle = 'rgba(255, 147, 170, .4)';
    ctx.beginPath(); ctx.arc(-s * .12, ey + s * .06, s * .03, 0, 6.3); ctx.fill();
    ctx.beginPath(); ctx.arc(s * .12, ey + s * .06, s * .03, 0, 6.3); ctx.fill();
    // tiny elemental sparkle
    const sc = sp.type === 'Leaf' ? '#b9f7c3' : sp.type === 'Flame' ? '#ffd08a' : sp.type === 'Water' ? '#bff0ff' : '#fff3a0';
    ctx.fillStyle = sc;
    const spx = Math.sin(this.time * 2 + 2) * s * .25;
    ctx.beginPath(); ctx.arc(spx, -s * (adult ? 1.02 : .98), s * .025, 0, 6.3); ctx.fill();
    ctx.restore();
  }

  drawAmbient(ctx, w, h) {
    ctx.save();
    for (const p of this.ambient) {
      ctx.globalAlpha = p.a;
      if (p.kind === 'petal') {
        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate(p.rot);
        ctx.fillStyle = '#ffd0dc';
        ctx.beginPath();
        ctx.ellipse(0, 0, p.s, p.s * .6, 0, 0, 6.3);
        ctx.fill();
        ctx.restore();
      } else {
        ctx.fillStyle = '#fff6c9';
        ctx.beginPath(); ctx.arc(p.x, p.y, p.s * .42, 0, 6.3); ctx.fill();
      }
    }
    ctx.restore();
  }
}

/* ════════════════════════════════════════════════════════════════
   battle.js — turn-based Bloomkin duels
   ════════════════════════════════════════════════════════════════ */

import { MOVES, SPECIES, TYPE_CHART, TYPE_META, ITEMS, statsFor, makeCreature, xpToNext, clamp, pick } from './data.js';
import { monsterSVG } from './art.js';
import { statsOf, addXp, addCreature } from './state.js';
import { $, typeChipSmall, hpClass, teamGridHTML, toast, bigToast } from './ui.js';
import { audio } from './audio.js';

const wait = ms => new Promise(res => setTimeout(res, ms));

export class Battle {
  constructor(game) {
    this.game = game;
    this.root = $('#battle-screen');
    this.zone = 'route';
    this.busy = false;
    this.battleOver = false;
    this.wild = true;
    this.trainer = null;
    this.trainerId = null;
    this.enemyTeam = [];
    this.enemyIndex = 0;
    this.playerIndex = 0;
    this.turn = 0;
    this.forcedSwitch = false;
    this.xpEarned = 0;
    this.coinsEarned = 0;
    this.logLines = [];
    this.tab = 'fight';
    this._bound = false;
    this.bindEvents();
  }

  get state() { return this.game.state; }
  activePlayer() { return this.state.party[this.playerIndex]; }
  activeEnemy() { return this.enemyTeam[this.enemyIndex]; }

  bindEvents() {
    if (this._bound) return;
    this._bound = true;
    $('#battle-tabs').addEventListener('click', e => {
      const b = e.target.closest('.btab');
      if (!b || this.busy || this.forcedSwitch) return;
      audio.sfx('click');
      const tab = b.dataset.tab;
      if (tab === 'run') { this.tryRun(); return; }
      this.tab = tab;
      this.renderActions();
    });
    $('#battle-actions').addEventListener('click', e => {
      if (this.busy) return;
      const move = e.target.closest('[data-move]');
      if (move) { this.useMove(move.dataset.move); return; }
      const item = e.target.closest('[data-item]');
      if (item) { this.useBag(item.dataset.item); return; }
      const team = e.target.closest('[data-team]');
      if (team) { this.selectTeam(Number(team.dataset.team)); return; }
    });
    $('#battle-log-toggle').addEventListener('click', () => {
      $('#battle-log').classList.toggle('hidden');
      audio.sfx('click');
    });
  }

  /* ─────────────── setup ─────────────── */

  async start({ enemyTeam, wild = true, trainer = null, trainerId = null, zone = 'route' }) {
    this.wild = wild;
    this.trainer = trainer;
    this.trainerId = trainerId;
    this.zone = zone;
    this.enemyTeam = enemyTeam.map(c => {
      if (typeof c === 'string') return makeCreature(c, 5);
      if (c.species) return { species: c.species, level: c.level, xp: 0, hp: statsFor(c.species, c.level).maxHp, bond: 1 };
      return c;
    });
    this.enemyIndex = 0;
    this.playerIndex = this.state.party.findIndex(c => c.hp > 0);
    if (this.playerIndex < 0) this.playerIndex = 0;
    this.busy = true;
    this.battleOver = false;
    this.forcedSwitch = false;
    this.turn = 0;
    this.xpEarned = 0;
    this.coinsEarned = 0;
    this.logLines = [];
    this.tab = 'fight';

    this.root.classList.remove('hidden');
    this.root.classList.remove('zone-forest', 'zone-shrine', 'zone-meadow', 'zone-town', 'zone-route');
    this.root.classList.add('zone-' + zone);
    $('#battle-log').classList.add('hidden');
    $('#battle-log').innerHTML = '';
    $('#battle-log-toggle').classList.remove('hidden');
    $('#battle-banner').classList.add('hidden');
    $('#damage-layer').innerHTML = '';

    this.setPlayer(this.activePlayer(), true);
    this.setEnemy(this.activeEnemy(), true);
    this.updateBars();
    this.renderActions();

    const lead = this.activePlayer();
    const en = this.activeEnemy();
    if (!lead || !en) { this.game.onBattleEnd({ result: 'lose' }); return; }

    if (this.trainer) {
      this.say(`${this.trainer.name} challenges you!`);
      this.log(`${this.trainer.name} challenges you!`);
    } else {
      this.say(`A wild ${SPECIES[en.species].name} appeared!`);
      this.log(`A wild ${SPECIES[en.species].name} appeared!`);
    }
    await wait(650);
    this.say(`Go, ${SPECIES[lead.species].name}!`);
    this.log(`Go, ${SPECIES[lead.species].name}!`);
    await wait(500);
    this.say(`What will ${SPECIES[lead.species].name} do?`);
    this.busy = false;
    this.showActions();
  }

  setPlayer(c, enter = false) {
    if (!c) return;
    const sp = SPECIES[c.species];
    const max = statsOf(c).maxHp;
    $('#player-art').innerHTML = monsterSVG(sp);
    $('#battle-player-name').textContent = sp.name;
    $('#battle-player-lv').textContent = 'Lv. ' + c.level;
    $('#battle-player-types').innerHTML = typeChipSmall(sp.type);
    $('#battle-player-hp-num').textContent = `${Math.max(0, Math.round(c.hp))} / ${max}`;
    const pm = $('#player-mon');
    if (enter) {
      pm.classList.remove('faint', 'enter');
      void pm.offsetWidth;
      pm.classList.add('enter');
    }
  }

  setEnemy(c, enter = false) {
    if (!c) return;
    const sp = SPECIES[c.species];
    const max = statsOf(c).maxHp;
    $('#enemy-art').innerHTML = monsterSVG(sp);
    $('#enemy-name').textContent = sp.name;
    $('#enemy-lv').textContent = 'Lv. ' + c.level;
    $('#enemy-types').innerHTML = typeChipSmall(sp.type);
    $('#enemy-hp-num').textContent = `${Math.max(0, Math.round(c.hp))} / ${max}`;
    const em = $('#enemy-mon');
    if (enter) {
      em.classList.remove('faint', 'enter');
      void em.offsetWidth;
      em.classList.add('enter');
    }
  }

  updateBars() {
    const p = this.activePlayer();
    const e = this.activeEnemy();
    if (p) {
      const max = statsOf(p).maxHp;
      const ratio = clamp(p.hp / max, 0, 1);
      const fill = $('#battle-player-hp');
      fill.style.width = (ratio * 100) + '%';
      fill.className = 'hp-fill ' + hpClass(ratio);
      $('#battle-player-hp-num').textContent = `${Math.max(0, Math.round(p.hp))} / ${max}`;
      const need = xpToNext(p.level);
      $('#battle-player-xp').style.width = clamp(p.xp / need, 0, 1) * 100 + '%';
    }
    if (e) {
      const max = statsOf(e).maxHp;
      const ratio = clamp(e.hp / max, 0, 1);
      const fill = $('#enemy-hp');
      fill.style.width = (ratio * 100) + '%';
      fill.className = 'hp-fill ' + hpClass(ratio);
      $('#enemy-hp-num').textContent = `${Math.max(0, Math.round(e.hp))} / ${max}`;
    }
  }

  /* ─────────────── messaging ─────────────── */

  say(text) {
    $('#battle-msg').textContent = text;
  }

  log(text) {
    this.logLines.push(text);
    if (this.logLines.length > 40) this.logLines.shift();
    const el = $('#battle-log');
    el.innerHTML = this.logLines.map(t => `<p>${t}</p>`).join('');
    el.scrollTop = el.scrollHeight;
  }

  async pause(ms = 500) { await wait(ms); }

  /* ─────────────── actions ─────────────── */

  showActions() {
    if (this.battleOver) return;
    this.renderActions();
    this.updateBars();
  }

  renderActions() {
    if (this.forcedSwitch) {
      $('#battle-tabs').classList.add('hidden');
      this.renderForcedSwitch();
      return;
    }
    $('#battle-tabs').classList.remove('hidden');
    document.querySelectorAll('.btab').forEach(b => b.classList.toggle('active', b.dataset.tab === this.tab));
    if (this.tab === 'fight') this.renderMoves();
    else if (this.tab === 'bag') this.renderBag();
    else if (this.tab === 'team') this.renderTeam();
    else this.renderMoves();
  }

  renderMoves() {
    const p = this.activePlayer();
    const sp = SPECIES[p.species];
    $('#battle-actions').innerHTML = sp.moves.map(id => {
      const m = MOVES[id];
      const c = TYPE_META[m.type];
      const meta = m.power ? `Power ${m.power}` : 'Heals';
      return `<button class="move-btn" data-move="${id}" style="--mt:${c.color}">
        <span class="m-name">${m.name}</span>
        <span class="m-meta"><b>${c.icon} ${m.type}</b> · ${meta}</span>
      </button>`;
    }).join('');
  }

  renderBag() {
    const items = this.state.player.items;
    const p = this.activePlayer();
    const max = statsOf(p).maxHp;
    const rows = [];
    if (this.wild) {
      rows.push(this.bagButton('orb', items.orb || 0, max));
    }
    rows.push(this.bagButton('potion', items.potion || 0, max));
    rows.push(this.bagButton('tea', items.tea || 0, max));
    $('#battle-actions').innerHTML = `<div class="bag-grid">${rows.join('')}</div>`;
  }

  bagButton(id, count, max) {
    const item = ITEMS[id];
    const p = this.activePlayer();
    const full = p.hp >= max;
    const disabled = count <= 0 || ((id === 'potion' || id === 'tea') && full);
    const reason = count <= 0 ? 'None left' : full ? 'Already full HP' : item.desc;
    return `<button class="bag-item" data-item="${id}" ${disabled ? 'disabled' : ''}>
      <span class="ic">${item.icon}</span>
      <span><span>${item.name} ×${count}</span><small>${reason}</small></span>
    </button>`;
  }

  renderTeam() {
    const p = this.activePlayer();
    const inner = this.state.party.map((c, i) => {
      const sp = SPECIES[c.species];
      const max = statsOf(c).maxHp;
      const ratio = clamp(c.hp / max, 0, 1);
      const pct = Math.max(0, ratio * 100);
      return `<button class="team-card ${i === this.playerIndex ? 'active' : ''} ${c.hp <= 0 ? 'fainted' : ''}" data-team="${i}" ${c.hp <= 0 || i === this.playerIndex ? 'disabled' : ''}>
        <div class="tc-art">${monsterSVG(sp)}</div>
        <div>
          <div class="tc-name">${sp.name} <span class="hint">Lv.${c.level}</span></div>
          <div class="tc-sub">${sp.type}${c.hp <= 0 ? ' · fainted' : ''}</div>
          <div class="hp-mini"><i style="width:${pct}%;background:${ratio <= .22 ? '#d94747' : ratio <= .5 ? '#e6a92e' : '#3db765'}"></i></div>
        </div>
      </button>`;
    }).join('');
    $('#battle-actions').innerHTML = `<div class="team-grid">${inner}</div>`;
  }

  renderForcedSwitch() {
    this.say('Choose your next Bloomkin!');
    const inner = this.state.party.map((c, i) => {
      const sp = SPECIES[c.species];
      const max = statsOf(c).maxHp;
      const ratio = clamp(c.hp / max, 0, 1);
      return `<button class="team-card ${c.hp <= 0 ? 'fainted' : ''}" data-team="${i}" ${c.hp <= 0 ? 'disabled' : ''}>
        <div class="tc-art">${monsterSVG(sp)}</div>
        <div>
          <div class="tc-name">${sp.name} <span class="hint">Lv.${c.level}</span></div>
          <div class="tc-sub">${sp.type}${c.hp <= 0 ? ' · fainted' : ''}</div>
          <div class="hp-mini"><i style="width:${Math.max(0, ratio * 100)}%"></i></div>
        </div>
      </button>`;
    }).join('');
    const none = this.state.party.every(c => c.hp <= 0);
    $('#battle-actions').innerHTML = `<div class="team-grid">${inner}${none ? '<p class="hint" style="grid-column:1/-1">No one is able to fight…</p>' : ''}</div>`;
  }

  /* ─────────────── player choices ─────────────── */

  async useMove(moveId) {
    if (this.busy || this.battleOver) return;
    this.busy = true;
    this.tab = 'fight';
    const p = this.activePlayer();
    const e = this.activeEnemy();
    const move = MOVES[moveId];
    if (!p || !e || !move) { this.busy = false; return; }
    audio.sfx('click');
    await this.performRound({ type: 'move', moveId });
    if (!this.battleOver && !this.forcedSwitch) {
      this.busy = false;
      this.tab = 'fight';
      this.showActions();
    }
  }

  async useBag(itemId) {
    if (this.busy || this.battleOver) return;
    this.busy = true;
    audio.sfx('click');
    this.tab = 'bag';
    await this.performRound({ type: 'item', itemId });
    if (!this.battleOver && !this.forcedSwitch) {
      this.busy = false;
      this.tab = 'fight';
      this.showActions();
    }
  }

  async selectTeam(index) {
    if (this.busy || this.battleOver) return;
    const c = this.state.party[index];
    if (!c || c.hp <= 0) return;
    if (index === this.playerIndex && !this.forcedSwitch) return;
    audio.sfx('select');

    if (this.forcedSwitch) {
      this.busy = true;
      this.playerIndex = index;
      this.forcedSwitch = false;
      this.setPlayer(c, true);
      this.updateBars();
      this.say(`Go, ${SPECIES[c.species].name}!`);
      this.log(`Go, ${SPECIES[c.species].name}!`);
      await wait(600);
      this.busy = false;
      this.tab = 'fight';
      this.showActions();
      return;
    }

    this.busy = true;
    this.tab = 'team';
    await this.performRound({ type: 'switch', index });
    if (!this.battleOver && !this.forcedSwitch) {
      this.busy = false;
      this.tab = 'fight';
      this.showActions();
    }
  }

  async tryRun() {
    if (this.busy || this.battleOver) return;
    if (!this.wild) {
      this.say('There is no running from a keeper\'s challenge!');
      this.log('There is no running from a keeper\'s challenge!');
      audio.sfx('fail');
      return;
    }
    this.busy = true;
    audio.sfx('click');
    this.say('You slip away through the tall grass…');
    this.log('You slip away through the tall grass…');
    await wait(700);
    await this.finish({ result: 'run' });
  }

  /* ─────────────── round engine ─────────────── */

  async performRound(action) {
    const p = this.activePlayer();
    const e = this.activeEnemy();
    if (!p || !e) return;

    if (action.type === 'item') {
      if (action.itemId === 'orb') {
        if (!this.wild) {
          this.say('You can\'t bond with another keeper\'s Bloomkin!');
          this.log('You can\'t bond with another keeper\'s Bloomkin!');
          audio.sfx('fail');
          await wait(650);
          return;
        }
        await this.attemptCatch();
        if (this.battleOver) return;
        // failed catch: enemy gets a turn
        await this.enemyTurn();
        return;
      }
      this.state.player.items[action.itemId]--;
      const item = ITEMS[action.itemId];
      const max = statsOf(p).maxHp;
      const heal = Math.min(item.heal, max - p.hp);
      p.hp += heal;
      audio.sfx('heal');
      this.say(`${SPECIES[p.species].name} drank the ${item.name} and recovered ${heal} HP!`);
      this.log(`${SPECIES[p.species].name} recovered ${heal} HP.`);
      this.damageNumber('player', '+' + heal, false, true);
      this.updateBars();
      await wait(700);
      await this.enemyTurn();
      return;
    }

    if (action.type === 'switch') {
      this.playerIndex = action.index;
      this.setPlayer(this.activePlayer(), true);
      this.updateBars();
      this.say(`Go, ${SPECIES[this.activePlayer().species].name}!`);
      this.log(`Switched to ${SPECIES[this.activePlayer().species].name}.`);
      audio.sfx('select');
      await wait(650);
      await this.enemyTurn();
      return;
    }

    if (action.type === 'move') {
      const playerFirst = p.spd > e.spd || (p.spd === e.spd && Math.random() < .5);
      if (playerFirst) {
        await this.doMove('player', p, e, action.moveId);
        if (await this.checkFaint('enemy')) return;
        await this.enemyTurn();
      } else {
        await this.enemyTurn();
        if (this.battleOver || this.forcedSwitch) return;
        if (this.activePlayer() && this.activePlayer().hp > 0) {
          await this.doMove('player', this.activePlayer(), this.activeEnemy(), action.moveId);
          await this.checkFaint('enemy');
        }
      }
      return;
    }
  }

  async enemyTurn() {
    if (this.battleOver) return;
    const e = this.activeEnemy();
    const p = this.activePlayer();
    if (!e || !p || e.hp <= 0 || p.hp <= 0) return;
    const moveId = this.chooseEnemyMove(e, p);
    await this.doMove('enemy', e, p, moveId);
    await this.checkFaint('player');
  }

  chooseEnemyMove(e, p) {
    const sp = SPECIES[e.species];
    const moves = sp.moves;
    const healMove = moves.find(id => MOVES[id].heal && e.hp / statsOf(e).maxHp < .38);
    if (healMove && Math.random() < .55) return healMove;
    const scored = moves.filter(id => MOVES[id].power).map(id => {
      const m = MOVES[id];
      const eff = (TYPE_CHART[m.type] && TYPE_CHART[m.type][SPECIES[p.species].type]) || 1;
      return { id, score: m.power * eff + Math.random() * 4 };
    });
    scored.sort((a, b) => b.score - a.score);
    return scored.length ? scored[0].id : moves[0];
  }

  async doMove(side, attacker, defender, moveId) {
    const move = MOVES[moveId];
    if (!move) return;
    const aSp = SPECIES[attacker.species];
    const dSp = SPECIES[defender.species];
    this.say(`${aSp.name} used ${move.name}!`);
    this.log(`${aSp.name} used ${move.name}!`);
    audio.sfx('select');
    await wait(320);

    if (move.heal) {
      const max = statsOf(attacker).maxHp;
      const amount = Math.min(max - attacker.hp, Math.round(max * move.heal));
      attacker.hp += amount;
      audio.sfx('heal');
      this.animateAttack(side);
      if (side === 'player') this.floatHeal('player', amount); else this.floatHeal('enemy', amount);
      this.updateBars();
      this.say(`${aSp.name} glows softly and recovers ${amount} HP!`);
      this.log(`${aSp.name} recovered ${amount} HP.`);
      await wait(700);
      return;
    }

    this.animateAttack(side);
    await wait(160);
    const crit = Math.random() < .08;
    const eff = (TYPE_CHART[move.type] && TYPE_CHART[move.type][dSp.type]) || 1;
    const atk = statsOf(attacker).atk;
    const def = statsOf(defender).def;
    let dmg = (move.power + atk * .48 - def * .3) * (.9 + Math.random() * .2);
    dmg *= eff;
    if (crit) dmg *= 1.55;
    dmg = Math.max(1, Math.round(dmg));
    defender.hp = Math.max(0, defender.hp - dmg);

    if (crit || eff > 1.3) audio.sfx('super'); else if (eff < .8) audio.sfx('weak'); else audio.sfx('hit');
    this.hitAnim(side === 'player' ? 'enemy' : 'player');
    this.shakeScene();
    this.damageNumber(side === 'player' ? 'enemy' : 'player', String(dmg), crit);
    this.updateBars();
    await wait(340);
    if (crit) { this.say('A critical bloom!'); await wait(420); }
    if (eff > 1.3) { this.say('It\'s super effective!'); this.log('It\'s super effective!'); await wait(460); }
    else if (eff < .8) { this.say('It\'s not very effective…'); this.log('It\'s not very effective…'); await wait(460); }
    this.say(`${dSp.name} took ${dmg} damage!`);
  }

  animateAttack(side) {
    const el = side === 'player' ? $('#player-mon') : $('#enemy-mon');
    el.classList.remove('attack-player', 'attack-enemy');
    void el.offsetWidth;
    el.classList.add(side === 'player' ? 'attack-player' : 'attack-enemy');
    setTimeout(() => el.classList.remove('attack-player', 'attack-enemy'), 450);
    const target = side === 'player' ? $('#enemy-mon') : $('#player-mon');
    setTimeout(() => {
      target.classList.remove('hit');
      void target.offsetWidth;
      target.classList.add('hit');
      setTimeout(() => target.classList.remove('hit'), 480);
    }, 170);
  }

  hitAnim(side) {
    const el = side === 'player' ? $('#player-mon') : $('#enemy-mon');
    el.classList.remove('hit');
    void el.offsetWidth;
    el.classList.add('hit');
    setTimeout(() => el.classList.remove('hit'), 480);
  }

  shakeScene() {
    const scene = $('.battle-scene');
    scene.classList.remove('shake');
    void scene.offsetWidth;
    scene.classList.add('shake');
    setTimeout(() => scene.classList.remove('shake'), 320);
  }

  damageNumber(side, text, crit = false, heal = false) {
    const scene = $('.battle-scene');
    const target = side === 'player' ? $('#player-mon') : $('#enemy-mon');
    if (!scene || !target) return;
    const sr = scene.getBoundingClientRect();
    const tr = target.getBoundingClientRect();
    const el = document.createElement('div');
    el.className = `dmg ${crit ? 'crit' : ''} ${heal ? 'heal' : ''}`;
    el.textContent = text;
    el.style.left = (tr.left - sr.left + tr.width * .5 - 20) + 'px';
    el.style.top = (tr.top - sr.top + tr.height * .22) + 'px';
    $('#damage-layer').appendChild(el);
    setTimeout(() => el.remove(), 1050);
    if (crit) this.sparkleBurst(side, 10);
  }

  floatHeal(side, amount) {
    this.damageNumber(side, '+' + amount, false, true);
    this.sparkleBurst(side, 8);
  }

  sparkleBurst(side, count = 8) {
    const scene = $('.battle-scene');
    const target = side === 'player' ? $('#player-mon') : $('#enemy-mon');
    if (!scene || !target) return;
    const sr = scene.getBoundingClientRect();
    const tr = target.getBoundingClientRect();
    for (let i = 0; i < count; i++) {
      const s = document.createElement('div');
      s.className = 'spark-p';
      s.style.left = (tr.left - sr.left + tr.width * (.2 + Math.random() * .6)) + 'px';
      s.style.top = (tr.top - sr.top + tr.height * (.2 + Math.random() * .5)) + 'px';
      s.style.setProperty('--dx', (Math.random() - .5) * 120 + 'px');
      s.style.setProperty('--dy', (-30 - Math.random() * 90) + 'px');
      $('#battle-particles').appendChild(s);
      setTimeout(() => s.remove(), 800);
    }
  }

  /* ─────────────── catching ─────────────── */

  async attemptCatch() {
    const e = this.activeEnemy();
    const sp = SPECIES[e.species];
    if (!this.state.player.items.orb || this.state.player.items.orb <= 0) {
      this.say('You have no Bond Orbs left.');
      return;
    }
    this.state.player.items.orb--;
    const max = statsOf(e).maxHp;
    const hpRatio = e.hp / max;
    const lead = this.activePlayer();
    let chance = .16 + (1 - hpRatio) * .66 + (lead.level - e.level) * .02;
    chance = clamp(chance, .06, .95);
    audio.sfx('select');
    this.say('You toss a Bond Orb…');
    this.log('You tossed a Bond Orb…');
    this.throwOrb();
    await wait(900);
    this.say('…');
    for (let i = 0; i < 3; i++) {
      audio.sfx('click');
      this.hitAnim('enemy');
      await wait(420);
    }
    if (Math.random() < chance) {
      audio.sfx('catch');
      bigToast('✿ Bond formed! ✿');
      this.sparkleBurst('enemy', 18);
      const caught = makeCreature(e.species, e.level);
      const where = addCreature(this.state, caught);
      this.state.seen[e.species] = true;
      this.say(`Gotcha! ${sp.name} joins your ${where.where === 'party' ? 'team' : 'reserve'}!`);
      this.log(`Caught ${sp.name}!`);
      this.updateBars();
      await wait(1100);
      await this.finish({ result: 'catch', caught: caught.species });
    } else {
      audio.sfx('fail');
      this.say(`Oh no! ${sp.name} broke free!`);
      this.log(`${sp.name} broke free.`);
      await wait(700);
    }
  }

  throwOrb() {
    const scene = $('.battle-scene');
    if (!scene) return;
    const orb = document.createElement('div');
    orb.className = 'orb-toss';
    orb.textContent = '◉';
    scene.appendChild(orb);
    setTimeout(() => orb.remove(), 1000);
  }

  /* ─────────────── faints & ends ─────────────── */

  async checkFaint(side) {
    if (side === 'enemy') {
      const e = this.activeEnemy();
      if (!e || e.hp > 0) return false;
      const sp = SPECIES[e.species];
      this.xpEarned += 14 + e.level * 7;
      this.coinsEarned += 9 + e.level * 3;
      $('#enemy-mon').classList.add('faint');
      audio.sfx('faint');
      this.say(`${sp.name} fainted!`);
      this.log(`${sp.name} fainted!`);
      await wait(850);
      $('#enemy-mon').classList.remove('faint');
      if (this.enemyIndex < this.enemyTeam.length - 1) {
        this.enemyIndex++;
        const next = this.activeEnemy();
        this.setEnemy(next, true);
        this.updateBars();
        const line = this.trainer ? `${this.trainer.name} sent out ${SPECIES[next.species].name}!` : `A wild ${SPECIES[next.species].name} appeared!`;
        this.say(line);
        this.log(line);
        await wait(800);
        return true;
      }
      await this.winBattle();
      return true;
    }

    const p = this.activePlayer();
    if (!p || p.hp > 0) return false;
    const sp = SPECIES[p.species];
    $('#player-mon').classList.add('faint');
    audio.sfx('faint');
    this.say(`${sp.name} fainted!`);
    this.log(`${sp.name} fainted!`);
    await wait(850);
    $('#player-mon').classList.remove('faint');
    const alive = this.state.party.some(c => c.hp > 0);
    if (!alive) { await this.loseBattle(); return true; }
    this.forcedSwitch = true;
    this.say('Choose your next Bloomkin!');
    this.renderActions();
    return true;
  }

  async winBattle() {
    if (this.battleOver) return;
    this.battleOver = true;
    this.busy = true;
    audio.sfx('victory');
    bigToast('✿ Victory! ✿', 1500);
    const lead = this.activePlayer();
    this.say('You won the battle!');
    this.log('You won the battle!');
    await wait(600);

    // XP: lead gets full, the rest of the team shares half
    const xp = this.xpEarned;
    if (lead && xp > 0) {
      const res = addXp(lead, xp);
      this.say(`${SPECIES[lead.species].name} gained ${xp} XP!`);
      this.log(`${SPECIES[lead.species].name} gained ${xp} XP.`);
      this.updateBars();
      await wait(700);
      for (const lvl of res.levels) {
        this.state.stats.levelUps++;
        audio.sfx('level');
        bigToast(`${SPECIES[lead.species].name} grew to Lv. ${lvl}!`, 1300);
        this.say(`${SPECIES[lead.species].name} grew to Lv. ${lvl}!`);
        this.log(`Level up! Now Lv. ${lvl}.`);
        this.updateBars();
        await wait(900);
      }
    }
    for (let i = 0; i < this.state.party.length; i++) {
      if (i === this.playerIndex) continue;
      const c = this.state.party[i];
      if (c.hp > 0 && xp > 0) addXp(c, Math.round(xp * .45));
    }
    this.updateBars();

    if (this.trainer && this.trainer.reward) {
      this.state.player.coins += this.trainer.reward.coins;
      this.coinsEarned = this.trainer.reward.coins;
    } else {
      this.state.player.coins += this.coinsEarned;
    }
    this.say(`Found ${this.coinsEarned} coins!`);
    await wait(750);
    await this.finish({ result: 'win', wild: this.wild, trainerId: this.trainerId, xp: xp });
  }

  async loseBattle() {
    if (this.battleOver) return;
    this.battleOver = true;
    this.busy = true;
    this.say('All your Bloomkin are tuckered out…');
    audio.sfx('faint');
    await wait(1200);
    await this.finish({ result: 'lose' });
  }

  async finish(extra) {
    this.battleOver = true;
    this.busy = true;
    await wait(300);
    this.root.classList.add('hidden');
    this.game.onBattleEnd(extra);
  }
}

/* ════════════════════════════════════════════════════════════════
   game.js — the beating heart of Bloom & Bond
   ════════════════════════════════════════════════════════════════ */

import {
  MAP, MAP_W, MAP_H, TILE, SPECIES, STARTERS, TRAINERS, NPCS, SIGNS, BUILDINGS, PROPS, ITEMS,
  TYPE_META, TYPE_CHART, QUEST_SEALS, MOVES, regionName, pickEncounter, makeCreature, statsFor,
  xpToNext, TIPS, clamp,
} from './data.js';
import {
  freshState, saveGame, loadGame, hasSave, deleteSave, healParty, addCreature, activeCreature,
  leadIndex, statsOf, sealCount, evolvable, evolveCreature, formatTime, SAVE_KEY,
} from './state.js';
import { monsterSVG, portraitSVG, typeColors } from './art.js';
import {
  $, $$, showDialogue, advanceDialogue, isDialogueOpen, closeDialogue, openModal, closeModal,
  isModalOpen, toast, bigToast, transition, typeChip, typeChipSmall, hpClass,
} from './ui.js';
import { Overworld } from './overworld.js';
import { Battle } from './battle.js';
import { audio } from './audio.js';

const wait = ms => new Promise(r => setTimeout(r, ms));

export class Game {
  constructor() {
    this.state = null;
    this.screen = 'title';
    this.busy = false;
    this.evolving = false;
    this.evoSkipResolve = null;
    this.battle = null;
    this.overworld = null;
    this.currentTarget = null;
    this.musicMode = 'title';
    this.lastSealCount = 0;
    this.playTimer = null;
    this._bindUI();
    this.initAudioPreference();
    this.buildTitle();
    this.startClock();
  }

  /* ─────────────── boot & title ─────────────── */

  initAudioPreference() {
    const pref = localStorage.getItem('bloom-and-bond-sound');
    if (pref === 'off') {
      audio.enabled = false;
      audio.setEnabled(false);
      $('#btn-sound').classList.add('muted');
      $('#btn-sound-title').classList.add('muted');
    }
    const kick = () => {
      audio.ensure();
      audio.mode = null;
      audio.setMusic(this.musicMode);
    };
    window.addEventListener('pointerdown', kick, { once: true });
    window.addEventListener('keydown', kick, { once: true });
  }

  startClock() {
    this.playTimer = setInterval(() => {
      if (this.state && this.screen !== 'title') {
        this.state.playSeconds++;
        if (this.state.playSeconds % 20 === 0) saveGame(this.state);
      }
    }, 1000);
  }

  buildTitle() {
    const box = $('#title-starters');
    box.innerHTML = STARTERS.map(id => `<div class="mini-mon">${monsterSVG(SPECIES[id])}</div>`).join('');
    const petals = $('#title-petals');
    for (let i = 0; i < 20; i++) {
      const p = document.createElement('div');
      p.className = 'petal';
      p.style.left = Math.random() * 100 + '%';
      p.style.animationDuration = (8 + Math.random() * 9) + 's';
      p.style.animationDelay = (-Math.random() * 14) + 's';
      p.style.setProperty('--drift', (Math.random() * 22 - 11) + 'vw');
      p.style.width = (7 + Math.random() * 9) + 'px';
      p.style.height = (5 + Math.random() * 6) + 'px';
      p.style.opacity = (.35 + Math.random() * .5).toFixed(2);
      petals.appendChild(p);
    }
    if (hasSave()) $('#btn-continue').classList.remove('hidden');
    this.setScreen('title');
    this.musicMode = 'title';
  }

  setScreen(name) {
    this.screen = name;
    const map = {
      title: '#title-screen', starter: '#starter-screen', game: '#game-screen',
      battle: '#battle-screen', evolution: '#evolution-screen', ending: '#ending-screen',
    };
    for (const [key, sel] of Object.entries(map)) {
      const el = $(sel);
      if (!el) continue;
      el.classList.toggle('hidden', key !== name);
    }
    if (name === 'game' && this.overworld) {
      setTimeout(() => this.overworld.resize(), 40);
    }
  }

  /* ─────────────── UI binding ─────────────── */

  _bindUI() {
    $('#btn-new').addEventListener('click', () => { audio.sfx('select'); this.requestNewGame(); });
    $('#btn-continue').addEventListener('click', () => { audio.sfx('select'); this.continueGame(); });
    $('#btn-howto').addEventListener('click', () => { audio.sfx('open'); this.openHowTo(); });
    $('#btn-starter-back').addEventListener('click', () => { audio.sfx('click'); this.setScreen('title'); this.musicMode = 'title'; audio.setMusic('title'); });
    $('#btn-sound-title').addEventListener('click', () => this.toggleSound());
    $('#btn-sound').addEventListener('click', () => this.toggleSound());
    $('#btn-team') && $('#btn-party')?.addEventListener('click', () => { audio.sfx('open'); this.openParty(); });

    $('#btn-party').addEventListener('click', () => { audio.sfx('open'); this.openParty(); });
    $('#btn-bag').addEventListener('click', () => { audio.sfx('open'); this.openBag(); });
    $('#btn-quest').addEventListener('click', () => { audio.sfx('open'); this.openQuest(); });
    $('#btn-map').addEventListener('click', () => { audio.sfx('open'); this.openMap(); });
    $('#btn-interact').addEventListener('click', () => this.pressA());
    $('#btn-back').addEventListener('click', () => { audio.sfx('open'); this.openPauseMenu(); });
    $('#modal-close').addEventListener('click', () => { audio.sfx('click'); closeModal(); });

    $('#modal').addEventListener('click', e => this.onModalClick(e));

    $('#btn-ending-continue').addEventListener('click', () => { audio.sfx('select'); this.resumeExploring(); });
    $('#btn-ending-title').addEventListener('click', () => { audio.sfx('click'); this.buildTitle(); saveGame(this.state); });

    // dialogue advance by tapping it
    $('#dialogue').addEventListener('pointerdown', e => { e.preventDefault(); advanceDialogue(); });
    $('#interact-prompt').addEventListener('pointerdown', e => { e.preventDefault(); this.pressA(); });

    this.bindTouchDpad();
    this.bindKeyboard();
    window.addEventListener('beforeunload', () => { if (this.state) saveGame(this.state); });
  }

  bindTouchDpad() {
    const dirs = ['up', 'down', 'left', 'right'];
    for (const dir of dirs) {
      const btn = document.querySelector(`.dp[data-dir="${dir}"]`);
      if (!btn) continue;
      const down = e => {
        e.preventDefault();
        if (this.overworld) this.overworld.setDirection(dir, true);
      };
      const up = e => {
        e.preventDefault();
        if (this.overworld) this.overworld.setDirection(dir, false);
      };
      btn.addEventListener('pointerdown', down);
      btn.addEventListener('pointerup', up);
      btn.addEventListener('pointercancel', up);
      btn.addEventListener('pointerleave', up);
      btn.addEventListener('lostpointercapture', up);
    }
  }

  bindKeyboard() {
    const map = { ArrowUp: 'up', ArrowDown: 'down', ArrowLeft: 'left', ArrowRight: 'right', w: 'up', s: 'down', a: 'left', d: 'right', W: 'up', S: 'down', A: 'left', D: 'right' };
    window.addEventListener('keydown', e => {
      if (e.target && /input|textarea/i.test(e.target.tagName)) return;
      if (this.screen === 'title') {
        if (e.key === 'Enter') { if (hasSave()) this.continueGame(); else this.requestNewGame(); }
        if (e.key === '?') this.openHowTo();
        return;
      }
      if (this.screen === 'starter') {
        const n = Number(e.key);
        if (n >= 1 && n <= STARTERS.length) this.chooseStarter(STARTERS[n - 1]);
        return;
      }
      if (this.screen !== 'game' && this.screen !== 'battle') return;

      const dir = map[e.key];
      if (dir) {
        e.preventDefault();
        if (this.screen === 'game' && !isDialogueOpen() && !isModalOpen()) {
          this.overworld?.setDirection(dir, true);
        }
        return;
      }
      if (e.key === 'e' || e.key === 'E' || e.key === 'Enter' || e.key === ' ' || e.key === 'Spacebar') {
        if (this.screen !== 'game') return;
        e.preventDefault();
        this.pressA();
        return;
      }
      if (e.key === 'Escape') {
        e.preventDefault();
        if (isModalOpen()) closeModal();
        else if (this.screen === 'game' && !isDialogueOpen()) this.openPauseMenu();
        return;
      }
      if (e.key === 'b' || e.key === 'B') { if (this.screen === 'game' && !isDialogueOpen()) this.openBag(); }
      if (e.key === 't' || e.key === 'T') { if (this.screen === 'game' && !isDialogueOpen()) this.openParty(); }
      if (e.key === 'm' || e.key === 'M') { if (this.screen === 'game' && !isDialogueOpen()) this.openMap(); }
      if (e.key === 'q' || e.key === 'Q') { if (this.screen === 'game' && !isDialogueOpen()) this.openQuest(); }
    });
    window.addEventListener('keyup', e => {
      const map2 = { ArrowUp: 'up', ArrowDown: 'down', ArrowLeft: 'left', ArrowRight: 'right', w: 'up', s: 'down', a: 'left', d: 'right', W: 'up', S: 'down', A: 'left', D: 'right' };
      const dir = map2[e.key];
      if (dir && this.overworld) this.overworld.setDirection(dir, false);
    });
  }

  toggleSound() {
    const on = audio.toggle();
    localStorage.setItem('bloom-and-bond-sound', on ? 'on' : 'off');
    $('#btn-sound').classList.toggle('muted', !on);
    $('#btn-sound-title').classList.toggle('muted', !on);
    if (on) { audio.ensure(); audio.mode = null; audio.setMusic(this.musicMode); toast('Sound on ♪'); }
    else toast('Sound off');
  }

  /* ─────────────── new / continue ─────────────── */

  requestNewGame() {
    if (!hasSave()) { this.openStarterPicker(); return; }
    openModal({
      title: 'Start a new journey?',
      body: `<p style="margin:4px 0;font-size:.88rem;line-height:1.55">A saved journey already exists. Starting over will replace it with a brand-new adventure.</p>
        <p class="hint" style="margin-top:6px">Your old party and seals will be lost.</p>`,
      foot: `<button class="btn ghost" data-action="cancel">Cancel</button><button class="btn primary" data-action="new-confirm">Start Over</button>`,
    });
  }

  openStarterPicker() {
    this.setScreen('starter');
    this.musicMode = 'title';
    audio.setMusic('title');
    const grid = $('#starter-grid');
    grid.innerHTML = STARTERS.map((id, i) => {
      const sp = SPECIES[id];
      const evo = SPECIES[sp.evolvesTo];
      const c = TYPE_META[sp.type];
      const statBar = (label, val, max) => `<div class="s-bar"><span>${label}</span><i><b style="width:${clamp(val / max * 100, 8, 100)}%;background:${c.color}"></b></i></div>`;
      return `<article class="starter-card" data-starter="${id}" style="--glow:${c.color}55">
        <div class="starter-art">${monsterSVG(sp)}</div>
        <span class="s-type" style="background:${c.color}">${c.icon} ${sp.type}</span>
        <h3>${sp.name}</h3>
        <p class="s-sub">${sp.title}</p>
        <p class="s-desc">${sp.desc}</p>
        <div class="s-bars">
          ${statBar('HP', sp.base.hp, 40)}
          ${statBar('ATK', sp.base.atk, 14)}
          ${statBar('SPD', sp.base.spd, 16)}
        </div>
        <div class="s-evo">Evolves at <b>Lv. ${sp.evolveLevel}</b> → <b>${evo.name}</b></div>
        <button class="btn primary" data-choose="${id}">Choose ${sp.name}</button>
      </article>`;
    }).join('');
    grid.onclick = e => {
      const b = e.target.closest('[data-choose]');
      if (!b) return;
      const id = b.dataset.choose;
      grid.querySelectorAll('.starter-card').forEach(c => c.classList.toggle('selected', c.dataset.starter === id));
      audio.sfx('select');
      this.chooseStarter(id);
    };
  }

  async chooseStarter(id) {
    if (this.busy) return;
    this.busy = true;
    const sp = SPECIES[id];
    const state = freshState();
    state.party.push(makeCreature(id, 5));
    state.seen[id] = true;
    state.flags.starterChosen = true;
    this.state = state;
    this.lastSealCount = 0;
    saveGame(state);
    audio.sfx('victory');
    await transition(300);
    this.enterWorld(true);
    this.busy = false;
    $('#btn-continue').classList.remove('hidden');
    showDialogue({
      name: 'Professor Lila', portrait: 'professor',
      lines: [
        `Oh, ${sp.name}! A wonderful choice. Look at those little cheeks — she's still a chibi.`,
        `Every Bloomkin grows when her bond matures. ${sp.name} will evolve at level 6, and she will grow into a grown-up ${SPECIES[sp.evolvesTo].name}.`,
        `Earn three Bloom Seals from Mira, Rowan, and Elowen. Then the Briar Shrine will open for you.`,
        `Walk through tall grass to meet wild Bloomkin. Weaken them, then use a Bond Orb to make a friend. Off you go, Wren!`,
      ],
      onDone: () => {
        saveGame(this.state);
        toast('Tip: press A or tap the action button to talk.', 'gold');
      },
    });
  }

  continueGame() {
    const state = loadGame();
    if (!state) { toast('No save found.'); return; }
    this.state = state;
    this.lastSealCount = sealCount(state);
    this.enterWorld(false);
    bigToast(`Welcome back, Wren`, 1400);
    if (state.flags.ending) toast('The vale is at peace. You can still explore!', 'gold');
  }

  enterWorld(isNew) {
    this.setScreen('game');
    this.musicMode = 'world';
    audio.setMusic('world');
    if (!this.overworld) {
      this.overworld = new Overworld($('#world'), this);
      this.battle = new Battle(this);
    }
    this.overworld.setState(this.state);
    this.overworld.start();
    this.overworld.setPaused(false);
    this.updateHUD();
    if (isNew) {
      setTimeout(() => this.overworld.resize(), 60);
    }
  }

  /* ─────────────── overworld hooks ─────────────── */

  overlayBlocking() {
    return this.screen !== 'game' || isDialogueOpen() || isModalOpen() || this.evolving || this.busy;
  }

  onStep() {
    if (!this.state) return;
    if (this.state.player.steps % 14 === 0) saveGame(this.state);
  }

  onRegionChange(name) {
    if (!this.state) return;
    this.state.location = name;
    $('#hud-loc').textContent = name;
    this.state.flags.visited = this.state.flags.visited || {};
    if (!this.state.flags.visited[name]) {
      this.state.flags.visited[name] = true;
      bigToast(name, 1200);
      saveGame(this.state);
    }
  }

  updatePrompt(target) {
    this.currentTarget = target;
    const prompt = $('#interact-prompt');
    const text = $('#interact-text');
    if (!target || this.screen !== 'game' || isDialogueOpen() || isModalOpen() || this.evolving) {
      prompt.classList.add('hidden');
      return;
    }
    prompt.classList.remove('hidden');
    text.textContent = target.label;
  }

  pressA() {
    if (isDialogueOpen()) { advanceDialogue(); return; }
    if (isModalOpen()) return;
    if (this.screen !== 'game' || this.busy || this.evolving) return;
    const t = this.currentTarget;
    if (t) this.interactWith(t);
  }

  sealCount() { return this.state ? sealCount(this.state) : 0; }

  /* ─────────────── interacting ─────────────── */

  async interactWith(target) {
    if (!this.state) return;
    audio.sfx('select');
    this.overworld.clearHeld();
    if (target.kind === 'sign') {
      showDialogue({ name: 'Weathered Sign', portrait: 'villager', lines: [target.sign.text] });
      return;
    }
    if (target.kind === 'building') {
      const lines = {
        cottage: ['A cozy cottage with rose vines around the door. Someone inside is humming.', 'The doorknob is warm. You feel welcome here.'],
        shop: ['Pip\'s Petals smells of honey and fresh soil. Talk to Pip outside to shop.'],
        hall: ['Lumen Hall. The town\'s Bloom Seals are awarded on its steps each spring.'],
        inn: ['The Sleeping Fern Inn. A sign reads: "Bloomkin welcome. Muddy paws welcome too."'],
        cabin: ['The grove cabin is quiet. A kettle whistles somewhere inside.'],
        shrine: ['The Briar Shrine hums with old magic. Queen Briar waits in the courtyard.'],
      };
      showDialogue({ name: target.building.name, portrait: 'villager', lines: (lines[target.building.kind] || ['The door is shut, but you hear gentle singing inside.']) });
      return;
    }
    if (target.kind === 'heal') {
      healParty(this.state);
      saveGame(this.state);
      this.updateHUD();
      audio.sfx('heal');
      bigToast('✿ Your team is fully rested! ✿', 1500);
      toast(target.prop.name + ' restores every Bloomkin.', 'gold');
      return;
    }
    if (target.kind === 'gate') {
      if (this.state.flags.gateOpened) {
        showDialogue({ name: 'Shrine Gate', portrait: 'queen', lines: ['The gate stands open. Petals drift down the steps like an invitation.'] });
      } else if (this.sealCount() >= 3) {
        this.state.flags.gateOpened = true;
        saveGame(this.state);
        audio.sfx('victory');
        bigToast('The Shrine Gate opens!', 1800);
        showDialogue({ name: 'Queen Briar', portrait: 'queen', lines: ['Three seals. Three bonds. The gate knows you now.', 'Come up to the shrine, bond-keeper. Let us see what you have grown.'] });
        this.updateHUD();
      } else {
        const n = this.sealCount();
        showDialogue({
          name: 'Sealed Gate', portrait: 'queen',
          lines: [`Ancient glyphs glow across the gate. ${n} of 3 seal sockets are filled.`, 'Mira keeps the meadow seal. Rowan keeps the town seal. Elowen keeps the grove seal.', 'Return when all three are yours.'],
        });
      }
      return;
    }
    if (target.kind === 'prop') {
      if (target.prop.kind === 'altar') {
        showDialogue({ name: 'Bloom Altar', portrait: 'queen', lines: ['A crown of living flowers floats above the altar.', 'It waits for the sovereign. Speak with Queen Briar to begin the final trial.'] });
      }
      return;
    }
    if (target.kind === 'npc') {
      const n = target.npc;
      if (n.shop) { this.openShop(); return; }
      if (n.trainer) { await this.talkToTrainer(n.trainer); return; }
      showDialogue({ name: n.name, portrait: n.portrait, lines: n.lines });
      return;
    }
  }

  async talkToTrainer(id) {
    const t = TRAINERS[id];
    if (!t) return;
    const done = !!this.state.flags.defeated[id];
    this.overworld.setPaused(true);
    if (done) {
      const lines = id === 'briar'
        ? ['The vale is brighter with you in it, Wren. Go on — grow more bonds.']
        : [`You've already earned my seal, and my friendship. Come visit anytime.`];
      showDialogue({ name: t.name, portrait: t.portrait, lines, onDone: () => this.overworld.setPaused(false) });
      return;
    }
    showDialogue({
      name: t.name, portrait: t.portrait, lines: t.intro,
      onDone: () => this.startTrainerBattle(id),
    });
  }

  /* ─────────────── battles ─────────────── */

  async startWildEncounter(zone) {
    if (this.busy || this.screen !== 'game' || isDialogueOpen() || isModalOpen()) return;
    const enc = pickEncounter(zone);
    const level = enc.min + Math.floor(Math.random() * (enc.max - enc.min + 1));
    this.state.seen[enc.species] = true;
    this.busy = true;
    this.overworld.setPaused(true);
    audio.sfx('open');
    await transition(260);
    this.overworld.stop();
    this.screen = 'battle';
    this.musicMode = 'battle';
    audio.setMusic('battle');
    this.battle.start({
      enemyTeam: [{ species: enc.species, level }],
      wild: true,
      zone,
    });
    this.busy = false;
  }

  async startTrainerBattle(id) {
    const t = TRAINERS[id];
    if (!t || this.busy) return;
    this.busy = true;
    this.overworld.setPaused(true);
    audio.sfx('open');
    await transition(300);
    this.overworld.stop();
    this.screen = 'battle';
    this.musicMode = 'battle';
    audio.setMusic('battle');
    this.state.stats.battles++;
    this.battle.start({
      enemyTeam: t.team.map(c => makeCreature(c.species, c.level)),
      wild: false,
      trainer: t,
      trainerId: id,
      zone: id === 'briar' ? 'shrine' : id === 'elowen' ? 'forest' : 'meadow',
    });
    this.busy = false;
  }

  async onBattleEnd(result) {
    if (!this.state) return;
    this.battle = this.battle;
    if (result.result === 'win') {
      this.state.stats.wins++;
      if (!result.wild && result.trainerId) {
        const t = TRAINERS[result.trainerId];
        const first = !this.state.flags.defeated[result.trainerId];
        this.state.flags.defeated[result.trainerId] = true;
        if (first && t.reward && t.reward.seal !== undefined) {
          this.state.player.seals[t.reward.seal] = true;
          this.lastSealCount = this.sealCount();
          setTimeout(() => audio.sfx('victory'), 300);
          bigToast('✿ Bloom Seal earned! ✿', 1800);
          this.hudSealPop();
        }
        if (t.reward && t.reward.finale) this.state.flags.ending = true;
      }
      saveGame(this.state);
    } else if (result.result === 'lose') {
      this.state.player.coins = Math.max(0, this.state.player.coins - 30);
      healParty(this.state);
      this.state.player.x = 10;
      this.state.player.y = 29;
      this.state.player.dir = 'up';
      saveGame(this.state);
    } else if (result.result === 'catch') {
      this.state.stats.caught++;
      saveGame(this.state);
      toast('A new bond joins your team!', 'rose');
    } else if (result.result === 'run') {
      saveGame(this.state);
    }

    await transition(200);
    this.setScreen('game');
    if (this.overworld) {
      this.overworld.setState(this.state);
      this.overworld.start();
      this.overworld.setPaused(true);
    }
    this.musicMode = 'world';
    audio.setMusic('world');
    this.updateHUD();
    this.busy = false;

    if (result.result === 'lose') {
      showDialogue({
        name: 'Professor Lila', portrait: 'professor',
        lines: ['There you are! I found you dozing in the meadow with your Bloomkin piled on top of you.', 'I healed everyone and carried you home. Take a breath, then try again. The vale is patient.'],
        onDone: () => { saveGame(this.state); this.overworld.setPaused(false); this.updateHUD(); },
      });
      return;
    }

    if (result.result === 'win' && result.trainerId) {
      const t = TRAINERS[result.trainerId];
      const wasFinale = t.reward && t.reward.finale;
      const lines = wasFinale
        ? [t.defeat, 'The crown dissolves into petals. The shrine fills with light, and every Bloomkin in the vale lifts her head.', 'You did not conquer the vale, Wren. You helped it bloom.']
        : [t.defeat];
      showDialogue({
        name: t.name, portrait: t.portrait, lines,
        onDone: async () => {
          this.overworld.setPaused(false);
          saveGame(this.state);
          if (wasFinale) { this.showEnding(); return; }
          await this.checkEvolutions();
        },
      });
      return;
    }

    this.overworld.setPaused(false);
    const evo = await this.checkEvolutions();
    if (result.result === 'win' || result.result === 'catch') {
      if (Math.random() < .35) setTimeout(() => toast(pick(TIPS)), 1200);
    }
  }

  hudSealPop() {
    const seals = $$('#hud-seals .seal');
    seals.forEach((el, i) => {
      el.classList.toggle('filled', !!this.state.player.seals[i]);
      if (this.state.player.seals[i]) {
        el.classList.add('pop');
        setTimeout(() => el.classList.remove('pop'), 700);
      }
    });
  }

  /* ─────────────── evolution ─────────────── */

  async checkEvolutions() {
    if (!this.state) return false;
    let did = false;
    for (const c of this.state.party) {
      if (evolvable(c)) {
        await this.runEvolution(c);
        did = true;
      }
    }
    return did;
  }

  async runEvolution(c) {
    const old = SPECIES[c.species];
    const to = SPECIES[old.evolvesTo];
    if (!to) return;
    this.evolving = true;
    const beforeHp = statsOf(c).maxHp;
    const beforeAtk = statsOf(c).atk;
    this.setScreen('evolution');
    $('#evolution-screen').classList.remove('hidden');
    $('#evo-old').className = 'evo-figure old';
    $('#evo-new').className = 'evo-figure new';
    $('#evo-old').innerHTML = monsterSVG(old);
    $('#evo-new').innerHTML = monsterSVG(to);
    $('#evo-title').textContent = `${old.name} is evolving!`;
    $('#evo-sub').textContent = `Her bond is blooming. She's growing into her true self…`;
    const stars = $('#evo-sparkles');
    stars.innerHTML = '';
    for (let i = 0; i < 26; i++) {
      const s = document.createElement('div');
      s.className = 'evo-star';
      s.style.left = Math.random() * 100 + '%';
      s.style.bottom = (Math.random() * 30) + '%';
      s.style.animationDelay = (-Math.random() * 3) + 's';
      s.style.animationDuration = (1.8 + Math.random() * 2.2) + 's';
      stars.appendChild(s);
    }
    this.musicMode = 'evolve';
    audio.setMusic('evolve');
    audio.sfx('evolve');

    let skipped = false;
    const skipPromise = new Promise(res => { this.evoSkipResolve = () => { skipped = true; res(); }; });
    const delay = ms => Promise.race([wait(ms), skipPromise]);

    await delay(1700);
    $('#evo-old').classList.add('gone');
    $('#evo-silhouette').classList.add('flash');
    audio.sfx('level');
    await delay(650);
    evolveCreature(c);
    this.state.stats.evolutions++;
    this.state.seen[to.id] = true;
    const afterHp = statsOf(c).maxHp;
    const afterAtk = statsOf(c).atk;
    $('#evo-new').classList.add('reveal');
    $('#evo-title').textContent = `${old.name} evolved into ${to.name}!`;
    $('#evo-sub').textContent = `She grew from a chibi into her grown-up form!  HP ${beforeHp} → ${afterHp} · ATK ${beforeAtk} → ${afterAtk}`;
    audio.sfx('victory');
    bigToast(`✿ ${to.name} blossomed! ✿`, 1900);
    await delay(skipped ? 900 : 2600);
    this.setScreen('game');
    this.overworld.setState(this.state);
    this.overworld.start();
    this.overworld.setPaused(false);
    this.updateHUD();
    saveGame(this.state);
    this.evolving = false;
    this.evoSkipResolve = null;
    this.musicMode = 'world';
    audio.setMusic('world');
    toast(`${to.name} is all grown up!`, 'gold');
  }

  /* ─────────────── HUD / quest ─────────────── */

  updateHUD() {
    if (!this.state) return;
    const lead = this.state.party.find(c => c.hp > 0) || this.state.party[0];
    if (lead) {
      const sp = SPECIES[lead.species];
      $('#hud-player-lv').textContent = 'Lv. ' + lead.level;
      $('#hud-avatar').textContent = TYPE_META[sp.type].icon;
      $('#hud-avatar').style.background = `radial-gradient(circle at 35% 28%, ${TYPE_META[sp.type].color}, ${TYPE_META[sp.type].deep} 72%)`;
    }
    $('#hud-loc').textContent = this.state.location || regionName(this.state.player.x, this.state.player.y);
    const seals = $$('#hud-seals .seal');
    seals.forEach((el, i) => {
      el.classList.toggle('filled', !!this.state.player.seals[i]);
    });
    const n = this.sealCount();
    const qTitle = $('#quest-title');
    const qText = $('#quest-text');
    if (this.state.flags.ending) {
      qTitle.textContent = 'A Vale at Peace';
      qText.textContent = 'The Bloom Court is restored. Keep exploring and raising your team.';
    } else if (n >= 3) {
      qTitle.textContent = 'The Shrine Awaits';
      qText.textContent = 'All three seals are yours. Climb to Briar Shrine and challenge Queen Briar.';
    } else {
      qTitle.textContent = 'The Bloom Trials';
      const next = QUEST_SEALS.find(q => !this.state.flags.defeated[q.id]);
      qText.textContent = next
        ? `Earn Bloom Seals from the keepers. (${n}/3) · Next: ${next.person}, ${next.place}.`
        : `Earn Bloom Seals from the keepers. (${n}/3)`;
    }
  }

  /* ─────────────── modals ─────────────── */

  openParty() {
    if (!this.state) return;
    this.openPartyModal();
  }

  openPartyModal() {
    const lead = this.state.party.findIndex(c => c.hp > 0);
    const rows = this.state.party.map((c, i) => {
      const sp = SPECIES[c.species];
      const st = statsOf(c);
      const ratio = clamp(c.hp / st.maxHp, 0, 1);
      const hearts = '♥'.repeat(Math.min(5, c.bond || 1)) + '♡'.repeat(Math.max(0, 5 - (c.bond || 1)));
      return `<div class="party-row ${i === lead ? 'active' : ''}">
        <div class="party-art">${monsterSVG(sp)}</div>
        <div class="party-main">
          <div class="party-name">${sp.name} <small>Lv. ${c.level}</small></div>
          <div class="party-sub">${typeChipSmall(sp.type)}<span class="hint">${sp.title}</span></div>
          <div class="party-bar"><i class="${hpClass(ratio)}" style="width:${ratio * 100}%"></i></div>
          <div class="party-hp">${Math.round(c.hp)} / ${st.maxHp} HP · ${c.xp}/${xpToNext(c.level)} XP</div>
          <div class="party-hp" style="color:#c95f7c">${hearts} bond · ATK ${st.atk} · DEF ${st.def} · SPD ${st.spd}</div>
        </div>
        <div class="party-actions">
          ${i === lead ? '<span class="hint" style="font-size:.58rem;font-weight:900;color:#a8792a">LEAD</span>' : `<button class="btn ghost" data-lead="${i}" ${c.hp <= 0 ? 'disabled' : ''}>Lead</button>`}
        </div>
      </div>`;
    }).join('');
    const reserve = this.state.box.length
      ? `<p class="party-note">Reserve meadow: ${this.state.box.map(c => SPECIES[c.species].name + ' Lv.' + c.level).join(' · ')}</p>`
      : '';
    openModal({
      title: 'Your Bloomkin',
      wide: true,
      body: `<div class="party-list">${rows}</div>${reserve}
        <p class="party-note">The lead Bloomkin fights first and walks beside you in the vale. Choose another lead to change the order.</p>`,
      foot: `<button class="btn ghost" data-action="know-types">Type Guide</button><button class="btn primary" data-action="close">Done</button>`,
    });
  }

  setLead(index) {
    if (!this.state) return;
    const c = this.state.party[index];
    if (!c || c.hp <= 0) return;
    this.state.party.splice(index, 1);
    this.state.party.unshift(c);
    audio.sfx('select');
    saveGame(this.state);
    this.updateHUD();
    this.openPartyModal();
    toast(`${SPECIES[c.species].name} is now your lead.`);
  }

  openBag() {
    if (!this.state) return;
    this.openBagModal();
  }

  openBagModal() {
    const items = this.state.player.items;
    const lead = this.state.party.find(c => c.hp > 0) || this.state.party[0];
    const phase = this.screen === 'battle' ? 'battle' : 'field';
    const rows = Object.values(ITEMS).map(item => {
      const count = items[item.id] || 0;
      const usable = (item.id === 'potion' || item.id === 'tea') && phase === 'field' && lead && lead.hp < statsOf(lead).maxHp && count > 0;
      const why = item.id === 'orb' ? (phase === 'battle' ? 'Use from the battle Bag tab.' : 'Used in wild battles.') : (lead && lead.hp >= statsOf(lead).maxHp ? 'Lead is already full.' : 'Restores your lead Bloomkin.');
      return `<div class="bag-row">
        <div class="bag-ic">${item.icon}</div>
        <div class="bag-main">
          <div class="bag-name">${item.name}</div>
          <div class="bag-desc">${item.desc}</div>
        </div>
        <span class="bag-count">×${count}</span>
        ${usable ? `<button class="btn primary" data-use="${item.id}" style="padding:8px 12px;font-size:.65rem">Use</button>` : `<span class="hint" style="font-size:.58rem;max-width:74px;text-align:right">${why}</span>`}
      </div>`;
    }).join('');
    openModal({
      title: 'Your Bag',
      body: `<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:9px">
          <span class="hint">Satchel of small kindnesses</span>
          <span class="coin-pill">✦ ${this.state.player.coins} coins</span>
        </div><div class="bag-list">${rows}</div>`,
      foot: `<button class="btn primary" data-action="close">Done</button>`,
    });
  }

  useFieldItem(id) {
    const lead = this.state.party.find(c => c.hp > 0) || this.state.party[0];
    if (!lead) return;
    if ((this.state.player.items[id] || 0) <= 0) { toast('You are out of those.'); return; }
    const max = statsOf(lead).maxHp;
    if (lead.hp >= max) { toast(`${SPECIES[lead.species].name} is already full of beans.`); return; }
    const heal = Math.min(ITEMS[id].heal, max - lead.hp);
    lead.hp += heal;
    this.state.player.items[id]--;
    audio.sfx('heal');
    toast(`${SPECIES[lead.species].name} recovered ${heal} HP.`, 'rose');
    saveGame(this.state);
    this.updateHUD();
    this.openBagModal();
  }

  openQuest() {
    if (!this.state) return;
    const n = this.sealCount();
    const rows = QUEST_SEALS.map((q, i) => {
      const done = !!this.state.flags.defeated[q.id];
      return `<div class="quest-row ${done ? 'done' : ''}">
        <div class="q-badge">${done ? '✓' : i + 1}</div>
        <div>
          <h4>${q.name} — ${q.person}</h4>
          <p>${done ? 'Earned! ' : ''}${q.hint}</p>
        </div>
      </div>`;
    }).join('');
    const finalRow = `<div class="quest-row ${this.state.flags.ending ? 'done' : ''}">
      <div class="q-badge">${this.state.flags.ending ? '✓' : '✿'}</div>
      <div><h4>The Bloom Sovereign</h4><p>${this.state.flags.ending ? 'Queen Briar has lowered her crown. The vale is at peace.' : 'Open the shrine gate with 3 seals, then defeat Queen Briar at Briar Shrine.'}</p></div>
    </div>`;
    openModal({
      title: 'Quest Log',
      body: `<p class="hint" style="margin:0 0 9px">${n}/3 Bloom Seals · ${this.state.stats.battles} battles · ${this.state.stats.caught} bonds made · ${formatTime(this.state.playSeconds)} roaming</p>
        <div class="quest-list">${rows}${finalRow}</div>
        <p class="party-note">Bloomkin evolve as they grow: starters at Lv. 6, wild Bloomkin at Lv. 9–10. Evolution also makes them visibly taller and more human-shaped.</p>`,
      foot: `<button class="btn primary" data-action="close">Done</button>`,
    });
  }

  openMap() {
    if (!this.state) return;
    openModal({
      title: 'Verdant Vale',
      wide: true,
      body: `<div class="map-wrap">
        <canvas class="map-canvas" id="mini-map" width="336" height="238"></canvas>
        <div class="map-legend">
          <span><i class="you"></i> You</span>
          <span><i class="npc"></i> Keepers</span>
          <span><i class="seal"></i> Seals</span>
          <span><i class="shrine"></i> Shrine</span>
          <span style="margin-top:6px" class="hint">${this.state.location}</span>
        </div>
      </div>
      <p class="party-note">Verdant Hollow → Sunbeam Route → Lumen Town → Whisperwood → Briar Shrine. Tall grass hides wild Bloomkin.</p>`,
      foot: `<button class="btn primary" data-action="close">Close Map</button>`,
    });
    this.drawMiniMap();
  }

  drawMiniMap() {
    const canvas = $('#mini-map');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const sx = canvas.width / MAP_W, sy = canvas.height / MAP_H;
    const colors = { '.': '#629f66', ',': '#68a96c', '#': '#d9c48f', '=': '#b6c0a9', H: '#3f8852', T: '#2d7447', W: '#3d8fbe', R: '#8d968e' };
    for (let y = 0; y < MAP_H; y++) for (let x = 0; x < MAP_W; x++) {
      ctx.fillStyle = colors[MAP[y][x]] || '#5c9c63';
      ctx.fillRect(x * sx, y * sy, sx + .5, sy + .5);
    }
    // buildings
    for (const b of BUILDINGS) {
      ctx.fillStyle = b.roof;
      ctx.fillRect(b.x * sx, b.y * sy, b.w * sx, b.h * sy);
    }
    // trainers
    for (const n of NPCS) {
      if (!n.trainer) continue;
      const done = !!this.state.flags.defeated[n.trainer];
      ctx.fillStyle = done ? 'rgba(255,255,255,.35)' : '#ff8fab';
      ctx.beginPath(); ctx.arc(n.x * sx + sx / 2, n.y * sy + sy / 2, Math.max(2.4, sx * .65), 0, 6.3); ctx.fill();
      if (!done) { ctx.strokeStyle = '#fff3b8'; ctx.lineWidth = 1; ctx.stroke(); }
    }
    // shop
    for (const n of NPCS) {
      if (!n.shop) continue;
      ctx.fillStyle = '#ffb84d';
      ctx.fillRect(n.x * sx - 1, n.y * sy - 1, sx + 2, sy + 2);
    }
    // shrine
    ctx.fillStyle = '#c7a4ff';
    ctx.beginPath(); ctx.arc(40 * sx, 8 * sy, Math.max(2.5, sx * .8), 0, 6.3); ctx.fill();
    // gate
    if (!this.state.flags.gateOpened) {
      ctx.fillStyle = '#e8e0bd';
      ctx.fillRect(35 * sx - 1, 10 * sy - 2, 3, sy + 4);
    }
    // player
    const px = this.state.player.x * sx + sx / 2, py = this.state.player.y * sy + sy / 2;
    ctx.fillStyle = 'rgba(255, 245, 190, .35)';
    ctx.beginPath(); ctx.arc(px, py, 7, 0, 6.3); ctx.fill();
    ctx.fillStyle = '#fff5be';
    ctx.strokeStyle = '#7a5a1c';
    ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.arc(px, py, 3.6, 0, 6.3); ctx.fill(); ctx.stroke();
  }

  openShop() {
    if (!this.state) return;
    this.openShopModal();
  }

  openShopModal() {
    const coins = this.state.player.coins;
    const rows = Object.values(ITEMS).map(item => `<div class="shop-row">
      <div class="bag-ic">${item.icon}</div>
      <div class="bag-main"><div class="bag-name">${item.name}</div><div class="bag-desc">${item.desc}</div></div>
      <button class="buy" data-buy="${item.id}" ${coins < item.price ? 'disabled' : ''}>✦ ${item.price}</button>
    </div>`).join('');
    openModal({
      title: "Pip's Petals",
      body: `<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:9px">
          <p class="hint" style="margin:0">"Everything a bond-keeper needs, and a few things she doesn't!"</p>
          <span class="coin-pill">✦ ${coins}</span>
        </div><div class="shop-grid">${rows}</div>`,
      foot: `<button class="btn ghost" data-action="close">Leave</button>`,
    });
  }

  buyItem(id) {
    const item = ITEMS[id];
    if (!item) return;
    if (this.state.player.coins < item.price) { toast('Not enough coins.'); return; }
    this.state.player.coins -= item.price;
    this.state.player.items[id] = (this.state.player.items[id] || 0) + 1;
    audio.sfx('catch');
    toast(`${item.name} purchased!`, 'gold');
    saveGame(this.state);
    this.openShopModal();
  }

  openHowTo() {
    openModal({
      title: 'How to Play',
      wide: true,
      body: `<div class="quest-list">
        <div class="quest-row"><div class="q-badge">1</div><div><h4>Explore</h4><p>Use the arrow keys / WASD, or the on-screen D-pad. Press A (or E / Enter / Space) to talk, read signs, heal, and open gates.</p></div></div>
        <div class="quest-row"><div class="q-badge">2</div><div><h4>Befriend</h4><p>Walk through tall grass to meet wild Bloomkin. Weaken them in battle, then throw a Bond Orb. A weakened Bloomkin is much easier to befriend.</p></div></div>
        <div class="quest-row"><div class="q-badge">3</div><div><h4>Bloom</h4><p>Your starter is a chibi at first. Reach Lv. 6 and she will evolve — growing visibly taller and more human-shaped. Wild lines evolve at Lv. 9–10.</p></div></div>
        <div class="quest-row"><div class="q-badge">4</div><div><h4>Triumph</h4><p>Defeat Mira, Rowan, and Elowen for three Bloom Seals. The shrine gate opens when all three are yours. Then challenge Queen Briar.</p></div></div>
      </div>
      <div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:12px">
        <span class="tchip" style="background:#58b978">❧ Leaf beats Water</span>
        <span class="tchip" style="background:#5eb7de">❉ Water beats Flame</span>
        <span class="tchip" style="background:#f0845d">✹ Flame beats Leaf</span>
        <span class="tchip" style="background:#e7bc4a">✦ Spark beats Water</span>
      </div>
      <p class="party-note">Phone/tablet: tap the D-pad to walk and the large A button to interact. Progress saves automatically. Use the ☰ button for Team, Bag, Quests, Map, Sound, and Save.</p>`,
      foot: `<button class="btn primary" data-action="close">Got it</button>`,
    });
  }

  openPauseMenu() {
    if (!this.state) return;
    openModal({
      title: 'Pause',
      body: `<div class="quest-list">
        <button class="quest-row" data-action="party" style="cursor:pointer;width:100%;text-align:left"><div class="q-badge">☘</div><div><h4>Team</h4><p>Check your Bloomkin, HP, levels, and set a new lead.</p></div></button>
        <button class="quest-row" data-action="bag" style="cursor:pointer;width:100%;text-align:left"><div class="q-badge">◈</div><div><h4>Bag</h4><p>Use potions, inspect Bond Orbs, count your coins.</p></div></button>
        <button class="quest-row" data-action="quest" style="cursor:pointer;width:100%;text-align:left"><div class="q-badge">✧</div><div><h4>Quest Log</h4><p>See your seals and the next step of the journey.</p></div></button>
        <button class="quest-row" data-action="map" style="cursor:pointer;width:100%;text-align:left"><div class="q-badge">▦</div><div><h4>Map</h4><p>A hand-drawn map of Verdant Vale.</p></div></button>
        <button class="quest-row" data-action="howto" style="cursor:pointer;width:100%;text-align:left"><div class="q-badge">?</div><div><h4>How to Play</h4><p>Controls, catching, evolution, and type matchups.</p></div></button>
        <button class="quest-row" data-action="sound" style="cursor:pointer;width:100%;text-align:left"><div class="q-badge">${audio.enabled ? '♪' : '—'}</div><div><h4>Sound: ${audio.enabled ? 'On' : 'Off'}</h4><p>Toggle the vale's music and sound effects.</p></div></button>
      </div>`,
      foot: `<button class="btn ghost" data-action="save">Save Game</button><button class="btn ghost" data-action="title">Title Screen</button><button class="btn primary" data-action="close">Resume</button>`,
    });
  }

  onModalClick(e) {
    const leadBtn = e.target.closest('[data-lead]');
    if (leadBtn) { this.setLead(Number(leadBtn.dataset.lead)); return; }
    const useBtn = e.target.closest('[data-use]');
    if (useBtn) { audio.sfx('click'); this.useFieldItem(useBtn.dataset.use); return; }
    const buyBtn = e.target.closest('[data-buy]');
    if (buyBtn) { audio.sfx('click'); this.buyItem(buyBtn.dataset.buy); return; }
    const action = e.target.closest('[data-action]');
    if (!action) return;
    const a = action.dataset.action;
    audio.sfx('click');
    if (a === 'close' || a === 'cancel') { closeModal(); return; }
    if (a === 'new-confirm') { closeModal(); deleteSave(); this.openStarterPicker(); return; }
    if (a === 'party') { this.openPartyModal(); return; }
    if (a === 'bag') { this.openBagModal(); return; }
    if (a === 'quest') { this.openQuest(); return; }
    if (a === 'map') { this.openMap(); return; }
    if (a === 'howto') { this.openHowTo(); return; }
    if (a === 'know-types') { this.openHowTo(); return; }
    if (a === 'sound') { this.toggleSound(); this.openPauseMenu(); return; }
    if (a === 'save') { saveGame(this.state); toast('Journey saved.', 'gold'); return; }
    if (a === 'title') { saveGame(this.state); closeModal(); this.buildTitle(); return; }
  }

  /* ─────────────── ending ─────────────── */

  showEnding() {
    if (!this.state) return;
    this.state.flags.ending = true;
    saveGame(this.state);
    this.overworld?.setPaused(true);
    this.musicMode = 'ending';
    audio.setMusic('ending');
    this.setScreen('ending');
    $('#ending-lede').textContent = 'Queen Briar lowers her crown. Verdant Vale blooms brighter than ever, and every bond you made is part of it.';
    $('#ending-team').innerHTML = this.state.party.map(c => `<div class="ending-mon">${monsterSVG(SPECIES[c.species])}</div>`).join('');
    const evoCount = this.state.stats.evolutions;
    $('#ending-stats').innerHTML = [
      `<span class="ending-stat"><b>${this.state.stats.wins}</b> battles won</span>`,
      `<span class="ending-stat"><b>${this.state.stats.caught}</b> bonds made</span>`,
      `<span class="ending-stat"><b>${evoCount}</b> evolution${evoCount === 1 ? '' : 's'}</span>`,
      `<span class="ending-stat"><b>${formatTime(this.state.playSeconds)}</b> together</span>`,
      `<span class="ending-stat"><b>3/3</b> Bloom Seals</span>`,
    ].join('');
    const petals = $('#ending-petals');
    petals.innerHTML = '';
    for (let i = 0; i < 20; i++) {
      const p = document.createElement('div');
      p.className = 'petal';
      p.style.left = Math.random() * 100 + '%';
      p.style.animationDuration = (8 + Math.random() * 8) + 's';
      p.style.animationDelay = (-Math.random() * 12) + 's';
      p.style.setProperty('--drift', (Math.random() * 16 - 8) + 'vw');
      petals.appendChild(p);
    }
    audio.sfx('victory');
  }

  resumeExploring() {
    this.setScreen('game');
    this.musicMode = 'world';
    audio.setMusic('world');
    if (this.overworld) {
      this.overworld.setState(this.state);
      this.overworld.start();
      this.overworld.setPaused(false);
    }
    this.updateHUD();
    toast('The vale is yours to wander.', 'gold');
  }
}

/* helper used by onBattleEnd for random tips */
function pick(arr) { return arr[Math.floor(Math.random() * arr.length)]; }

