          <button class="hud-btn" id="btn-map" aria-label="Open map"><span>▦</span><small>Map</small></button>
          <button class="hud-btn sound-hud" id="btn-sound" aria-label="Toggle sound"><span>♪</span><small>Sound</small></button>
        </div>
